{
  "name": "PulseStream PWA",
  "description": "A high-performance, real-time data streaming dashboard built as a Progressive Web App.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

const CACHE_NAME = 'pulse-stream-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/manifest.json'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS_TO_CACHE);
    })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request);
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.filter((name) => name !== CACHE_NAME).map((name) => caches.delete(name))
      );
    })
  );
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

// Register Service Worker
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').then(
      (registration) => {
        console.log('SW registered: ', registration);
      },
      (registrationError) => {
        console.log('SW registration failed: ', registrationError);
      }
    );
  });
}

export interface Message {
  id: string;
  sender: string;
  content: string;
  timestamp: number;
}

export interface MetricData {
  label: string;
  value: number;
  trend: 'up' | 'down' | 'stable';
}

export interface User {
  id: string;
  username: string;
  status: 'online' | 'away' | 'offline';
}

export interface AppState {
  messages: Message[];
  metrics: MetricData[];
  users: User[];
  isConnected: boolean;
  currentUser: User | null;
}

export enum SocketEvent {
  CONNECT = 'connect',
  DISCONNECT = 'disconnect',
  MESSAGE = 'message',
  METRIC_UPDATE = 'metric_update',
  USER_UPDATE = 'user_update'
}

// Fallback to a mock websocket server for demo if no ENV is provided
export const BACKEND_URL = (import.meta as any).env?.VITE_BACKEND_URL || 'wss://mock-socket-server.example.com';

export const INITIAL_METRICS = [
  { label: 'Network Latency', value: 24, trend: 'stable' },
  { label: 'Active Sessions', value: 120, trend: 'up' },
  { label: 'Throughput', value: 850, trend: 'up' },
  { label: 'Error Rate', value: 0.02, trend: 'down' },
];

export const MOCK_USERS = [
  { id: '1', username: 'alex_dev', status: 'online' },
  { id: '2', username: 'sarah_ops', status: 'away' },
  { id: '3', username: 'mike_qa', status: 'online' },
];

import { io, Socket } from 'socket.io-client';
import { BACKEND_URL } from '../constants';
import { SocketEvent } from '../types';

class SocketService {
  private socket: Socket | null = null;

  connect() {
    // In a real environment, this connects to BACKEND_URL.
    // Since we don't have a real backend, we'll simulate the socket behavior if the URL is mock.
    if (BACKEND_URL.includes('example.com')) {
        console.warn('SocketService: Using simulated real-time events.');
        return;
    }

    this.socket = io(BACKEND_URL, {
      transports: ['websocket'],
      reconnectionAttempts: 5,
    });
  }

  on(event: string, callback: (data: any) => void) {
    this.socket?.on(event, callback);
  }

  emit(event: string, data: any) {
    this.socket?.emit(event, data);
  }

  disconnect() {
    this.socket?.disconnect();
  }
}

export const socketService = new SocketService();

import { useState, useEffect } from 'react';

export const usePWA = () => {
  const [installPrompt, setInstallPrompt] = useState<any>(null);
  const [isStandalone, setIsStandalone] = useState(false);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    if (window.matchMedia('(display-mode: standalone)').matches) {
      setIsStandalone(true);
    }

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  const triggerInstall = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  return { installPrompt, isStandalone, triggerInstall };
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { socketService } from './services/socketService';
import { INITIAL_METRICS, MOCK_USERS } from './constants';
import { AppState, Message, MetricData, SocketEvent } from './types';
import { usePWA } from './hooks/usePWA';

// Components
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import MetricCard from './components/MetricCard';
import ChatPanel from './components/ChatPanel';
import InstallBanner from './components/InstallBanner';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    messages: [],
    metrics: INITIAL_METRICS as MetricData[],
    users: MOCK_USERS as any[],
    isConnected: false,
    currentUser: { id: 'me', username: 'MainUser', status: 'online' },
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'chat'>('dashboard');
  const { installPrompt, triggerInstall } = usePWA();

  // Simulated real-time updates for demonstration
  useEffect(() => {
    const interval = setInterval(() => {
      setState(prev => ({
        ...prev,
        metrics: prev.metrics.map(m => ({
          ...m,
          value: m.value + (Math.random() - 0.5) * 5,
          trend: Math.random() > 0.5 ? 'up' : 'down'
        }))
      }));
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    socketService.connect();

    // Simulate connection
    setTimeout(() => setState(prev => ({ ...prev, isConnected: true })), 1000);

    return () => {
      socketService.disconnect();
    };
  }, []);

  const handleSendMessage = useCallback((content: string) => {
    const newMessage: Message = {
      id: Date.now().toString(),
      sender: state.currentUser?.username || 'System',
      content,
      timestamp: Date.now(),
    };

    setState(prev => ({
      ...prev,
      messages: [...prev.messages, newMessage]
    }));

    // In production: socketService.emit(SocketEvent.MESSAGE, newMessage);
  }, [state.currentUser]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-100 selection:bg-blue-500 selection:text-white">
      <Sidebar activeTab={activeTab} onTabChange={setActiveTab} />

      <main className="flex flex-1 flex-col overflow-hidden">
        <Header isConnected={state.isConnected} currentUser={state.currentUser} />

        <div className="flex-1 overflow-y-auto p-4 md:p-8 no-scrollbar">
          {installPrompt && (
            <InstallBanner onInstall={triggerInstall} />
          )}

          {activeTab === 'dashboard' ? (
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
              {state.metrics.map((metric, idx) => (
                <MetricCard key={idx} metric={metric} />
              ))}

              <div className="col-span-full mt-6 rounded-2xl bg-slate-900/50 p-6 border border-slate-800 backdrop-blur-sm">
                <h3 className="mb-4 text-lg font-semibold text-slate-300">Live Pulse Activity</h3>
                <div className="h-64 w-full flex items-end justify-between gap-2 px-4">
                   {[...Array(20)].map((_, i) => (
                     <div 
                      key={i} 
                      className="w-full bg-blue-500/30 rounded-t-md animate-pulse" 
                      style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}
                    />
                   ))}
                </div>
              </div>
            </div>
          ) : (
            <ChatPanel 
              messages={state.messages} 
              onSend={handleSendMessage} 
              currentUser={state.currentUser} 
            />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

