import Header from '../components/Header';
import MetricCard from '../components/MetricCard';
import ChatPanel from '../components/ChatPanel';
import InstallBanner from '../components/InstallBanner';

const Dashboard: React.FC = () => {
  const { user } = useAuth();
  const [state, setState] = useState<AppState>({
    messages: [],
    metrics: INITIAL_METRICS as MetricData[],
    users: MOCK_USERS as any[],
    isConnected: false,
    currentUser: user,
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'chat'>('dashboard');
  const { installPrompt, triggerInstall } = usePWA();

  useEffect(() => {
    const interval = setInterval(() => {
      setState(prev => ({
        ...prev,
        metrics: prev.metrics.map(m => ({
          ...m,
          value: m.value + (Math.random() - 0.5) * 5,
          trend: Math.random() > 0.5 ? 'up' : 'down'
        }))
      }));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    socketService.connect();
    setTimeout(() => setState(prev => ({ ...prev, isConnected: true })), 1000);
    return () => { socketService.disconnect(); };
  }, []);

  const handleSendMessage = useCallback((content: string) => {
    const newMessage: Message = {
      id: Date.now().toString(),
      sender: user?.username || 'System',
      content,
      timestamp: Date.now(),
    };
    setState(prev => ({ ...prev, messages: [...prev.messages, newMessage] }));
  }, [user]);

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-100">
