// Initialize Socket.IO
const io = initSocket(server);
app.set('io', io);

const startServer = async () => {
  console.log('🔄 Starting Clientify Server...');
  try {
    // Fast fail-over: wait only 3 seconds for DB before entering demo mode
    const dbPromise = connectDB();
    const timeoutPromise = new Promise((_, reject) => 
      setTimeout(() => reject(new Error('MongoDB Connection Timeout')), 3000)
    );

    await Promise.race([dbPromise, timeoutPromise]);

    // Start watching database changes for real-time reactivity
    initChangeStreams(io);

    server.listen(PORT, () => {
      console.log(`🚀 Server running on port ${PORT}`);
      console.log(`📡 Health check at http://localhost:${PORT}/health`);
