import { API_BASE_URL } from '../constants';

class ApiService {
  private token: string | null = null;

  setToken(token: string | null) {
    this.token = token;
  }

  private getFullUrl(endpoint: string): string {
    const isProduction = window.location.hostname !== 'localhost' && !window.location.hostname.includes('127.0.0.1');
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;

    if (isProduction && !API_BASE_URL.includes('localhost')) {
        // Absolute path for production same-origin
        return `/api${cleanEndpoint}`;
    }

    const cleanBase = API_BASE_URL.replace(/\/$/, '');
    return `${cleanBase}/api${cleanEndpoint}`;
  }

  async get(endpoint: string) {
    const headers: HeadersInit = {};
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }

    const response = await fetch(this.getFullUrl(endpoint), { headers });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({ message: `HTTP Error ${response.status}` }));
      throw new Error(errorData.message || errorData.error || 'API request failed');
    }
    return await response.json();
  }

  async post(endpoint: string, data: any) {
    const headers: HeadersInit = {
      'Content-Type': 'application/json'
    };
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }

    const response = await fetch(this.getFullUrl(endpoint), {
      method: 'POST',
      headers,
      body: JSON.stringify(data),
    });

    const responseText = await response.text();
    let result;

    try {
      result = JSON.parse(responseText);
    } catch (e) {
      console.error('Failed to parse server response as JSON. Received:', responseText.substring(0, 100));
      throw new Error('Invalid server response: Expected JSON but received something else. Check if backend is running.');
    }

    if (!response.ok) {
      throw new Error(result.message || result.error || `Server Error (${response.status})`);
    }

    return result;
  }
}

export const api = new ApiService();

