  setToken(token: string | null) {
    this.token = token;
  }

  /**
   * Constructs the full URL for the API request.
   * Using relative paths (/api/...) allows the Vite proxy (dev) 
   * and the Express server (prod) to handle routing correctly.
   */
  private getFullUrl(endpoint: string): string {
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    // Always prefix with /api as defined in the backend routes
    return `/api${cleanEndpoint}`;
  }

  async get(endpoint: string) {
    const headers: HeadersInit = {};
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }

    const response = await fetch(this.getFullUrl(endpoint), { 
      method: 'GET',
      headers 
    });

    return this.handleResponse(response);
  }

  async post(endpoint: string, data: any) {
    const headers: HeadersInit = {
      'Content-Type': 'application/json'
    };
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }

    const response = await fetch(this.getFullUrl(endpoint), {
      method: 'POST',
      headers,
      body: JSON.stringify(data),
    });

    return this.handleResponse(response);
  }

  private async handleResponse(response: Response) {
    const responseText = await response.text();
    let result;

    try {
      result = responseText ? JSON.parse(responseText) : {};
    } catch (e) {
      console.error('Server response was not JSON:', responseText.substring(0, 100));
      throw new Error(`Invalid server response (${response.status}). The server might be down or misconfigured.`);
    }

    if (!response.ok) {
      throw new Error(result.message || result.error || result.message || `Request failed with status ${response.status}`);
    }

    return result;
  }
}

