class ApiService {
  private token: string | null = null;
  private minDelay = 800; // Minimum delay in ms to prevent UI flickering

  setToken(token: string | null) {
    this.token = token;
  }

  private getFullUrl(endpoint: string): string {
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    // If we are in production and have no BASE_URL set, warn the user
    if (!API_BASE_URL && window.location.hostname !== 'localhost') {
        console.error('VITE_BACKEND_URL is missing in environment variables!');
    }
    return `${API_BASE_URL}/api${cleanEndpoint}`;
  }

  async get(endpoint: string) {
    const start = Date.now();
    const headers: HeadersInit = {};
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }

    try {
        const response = await fetch(this.getFullUrl(endpoint), { 
          method: 'GET',
          headers 
        });

        // Wait for minimum delay if server was too fast
        const elapsed = Date.now() - start;
        if (elapsed < this.minDelay) {
            await new Promise(resolve => setTimeout(resolve, this.minDelay - elapsed));
        }

        return this.handleResponse(response);
    } catch (error) {
        console.error('API GET Error:', error);
        throw error;
    }
  }

  async post(endpoint: string, data: any) {
    const start = Date.now();
    const headers: HeadersInit = {
      'Content-Type': 'application/json'
    };
    if (this.token) {
      headers['Authorization'] = `Bearer ${this.token}`;
    }

    try {
        const response = await fetch(this.getFullUrl(endpoint), {
          method: 'POST',
          headers,
          body: JSON.stringify(data),
        });

        const elapsed = Date.now() - start;
        if (elapsed < this.minDelay) {
            await new Promise(resolve => setTimeout(resolve, this.minDelay - elapsed));
        }

        return this.handleResponse(response);
    } catch (error) {
        console.error('API POST Error:', error);
        throw error;
    }
  }

  private async handleResponse(response: Response) {
    const responseText = await response.text();
    let result;

    try {
      result = responseText ? JSON.parse(responseText) : {};
    } catch (e) {
      console.error('Server response was not JSON:', responseText.substring(0, 100));
      throw new Error(`Invalid server response (${response.status}). The server might be down or misconfigured.`);
    }

    if (!response.ok) {
      throw new Error(result.message || result.error || `Request failed with status ${response.status}`);
    }

    return result;
  }
}

