                    ))}
                    {state.messages.length === 0 && (
                      <p className="text-xs text-slate-500 italic text-center py-4">Waiting for real-time firm activity...</p>
                    )}
                  </div>
                  <button 
                    onClick={() => setActiveTab('chat')}
