import { API_BASE_URL } from '../constants';
import { mockBackend } from './mockBackend';

class ApiService {
  private token: string | null = null;
  private minDelay = 1200; 
  public isMockMode = false;

  setToken(token: string | null) {
    this.token = token;
  }

  private getFullUrl(endpoint: string): string {
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    return `${API_BASE_URL}/api${cleanEndpoint}`;
  }

  private async withMinDelay<T>(task: Promise<T>): Promise<T> {
    const start = Date.now();
    try {
      const result = await task;
      const elapsed = Date.now() - start;
      if (elapsed < this.minDelay) {
        await new Promise(resolve => setTimeout(resolve, this.minDelay - elapsed));
      }
      return result;
    } catch (error) {
      const elapsed = Date.now() - start;
      if (elapsed < this.minDelay) {
        await new Promise(resolve => setTimeout(resolve, this.minDelay - elapsed));
      }
      throw error;
    }
  }

  async get(endpoint: string) {
    // If we're in Mock Mode or no URL is set, use MockBackend
    if (!API_BASE_URL || this.isMockMode) {
      this.isMockMode = true;
      return this.withMinDelay(this.handleMockRequest('GET', endpoint));
    }

    try {
      const headers: HeadersInit = this.token ? { 'Authorization': `Bearer ${this.token}` } : {};
      const res = await fetch(this.getFullUrl(endpoint), { method: 'GET', headers });
      return this.withMinDelay(this.handleResponse(res));
    } catch (err) {
      console.warn('Backend unreachable, switching to Local Mock Mode.');
      this.isMockMode = true;
      return this.get(endpoint);
    }
  }

  async post(endpoint: string, data: any) {
    if (!API_BASE_URL || this.isMockMode) {
      this.isMockMode = true;
      return this.withMinDelay(this.handleMockRequest('POST', endpoint, data));
    }

    try {
      const headers: HeadersInit = {
        'Content-Type': 'application/json',
        ...(this.token ? { 'Authorization': `Bearer ${this.token}` } : {})
      };
      const res = await fetch(this.getFullUrl(endpoint), {
        method: 'POST',
        headers,
        body: JSON.stringify(data),
      });
      return this.withMinDelay(this.handleResponse(res));
    } catch (err) {
      console.warn('Backend unreachable, switching to Local Mock Mode.');
      this.isMockMode = true;
      return this.post(endpoint, data);
    }
  }

  /**
   * Routes requests to the internal Browser DB simulation
   */
  private async handleMockRequest(method: string, endpoint: string, data?: any) {
    console.debug(`[Mock API] ${method} ${endpoint}`, data || '');

    if (endpoint === '/auth/me' && this.token) return mockBackend.me(this.token);
    if (endpoint === '/auth/login') {
      const res = await mockBackend.login(data.user_id, data.password);
      this.token = res.token;
      return res;
    }
    if (endpoint === '/auth/signup') {
      const res = await mockBackend.signup(data);
      this.token = res.token;
      return res;
    }

    if (endpoint === '/items') {
      const userId = this.token?.replace('mock_token_', '') || 'guest';
      if (method === 'GET') return mockBackend.getItems(userId);
      if (method === 'POST') return mockBackend.createItem(userId, data);
    }

    return {};
  }

  private async handleResponse(response: Response) {
    const responseText = await response.text();
    let result;
    try {
      result = responseText ? JSON.parse(responseText) : {};
    } catch (e) {
      throw new Error(`Invalid server response (${response.status})`);
    }
    if (!response.ok) throw new Error(result.message || result.error || 'Request failed');
    return result;
  }
}

export const api = new ApiService();

import { io, Socket } from 'socket.io-client';
import { SOCKET_URL } from '../constants';
import { api } from './api';

class SocketService {
  private socket: Socket | null = null;
  private handlers: { [key: string]: Function[] } = {};

  connect() {
    if (api.isMockMode || !SOCKET_URL || SOCKET_URL.includes('example.com')) {
        console.debug('SocketService: Initializing local simulation.');
        this.simulateConnection();
        return;
    }

    try {
      this.socket = io(SOCKET_URL, {
        transports: ['websocket'],
        reconnectionAttempts: 5,
      });

      this.socket.on('connect', () => {
        console.debug('Socket Connected to Server');
        this.trigger('connect', {});
      });

      this.socket.onAny((event, ...args) => {
        this.trigger(event, args[0]);
      });

    } catch (e) {
      console.warn('Socket connection error, falling back to simulation.');
      this.simulateConnection();
    }
  }

  private simulateConnection() {
    setTimeout(() => this.trigger('connect', {}), 500);
  }

  on(event: string, callback: (data: any) => void) {
    if (this.socket) {
      this.socket.on(event, callback);
    }
    if (!this.handlers[event]) this.handlers[event] = [];
    this.handlers[event].push(callback);
  }

  private trigger(event: string, data: any) {
    this.handlers[event]?.forEach(cb => cb(data));
  }

  emit(event: string, data: any) {
    if (this.socket) {
      this.socket.emit(event, data);
    } else {
      console.debug(`[Mock Socket] Emit ${event}`, data);

      // Simulation Logic
      if (event === 'message') {
        // Echo back for UI feedback
        setTimeout(() => {
          this.trigger('message', {
            id: `mock_reply_${Date.now()}`,
            sender: 'VaultBot',
            content: `I received: "${data.content}". This is a real-time simulation.`,
            timestamp: Date.now()
          });
        }, 1000);
      }
    }
  }

  disconnect() {
    this.socket?.disconnect();
    this.socket = null;
  }
}

export const socketService = new SocketService();

