        },
        { id: 'admin-duedates', label: 'Due Date Setting', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /> },
        { id: 'settings', label: 'Settings', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /> },
        { id: 'trash', label: 'Trash', icon: <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /> },
      ]
    }
  ];

  useEffect(() => {
    const expandParents = (items: NavItem[], target: string, path: string[] = []): boolean => {
      for (const item of items) {
        if (item.id === target) {
          setExpandedFolders(prev => Array.from(new Set([...prev, ...path])));
          return true;
        }
        if (item.children) {
          if (expandParents(item.children, target, [...path, item.id])) return true;
        }
      }
      return false;
    };
    navigation.forEach(group => expandParents(group.items, activeView));
  }, [activeView]);

  const toggleFolder = (id: string) => {
    setExpandedFolders(prev => 
      prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]
    );
  };

  const handleItemClick = (item: NavItem, event: React.MouseEvent) => {
    const hasChildren = !!item.children?.length;

    if (isCollapsed && hasChildren) {
      const rect = event.currentTarget.getBoundingClientRect();
      setHoveredFolder({ item, top: rect.top });
      return;
    }

    if (hasChildren) {
      toggleFolder(item.id);
    } else {
      onViewChange(item.id as ActiveView);
      if (window.innerWidth < 768) onClose();
    }
  };

  const handleMouseEnter = (item: NavItem, event: React.MouseEvent) => {
    if (!isCollapsed || !item.children?.length) return;
    if (hoverTimeoutRef.current) window.clearTimeout(hoverTimeoutRef.current);

    const rect = event.currentTarget.getBoundingClientRect();
    setHoveredFolder({ item, top: rect.top });
  };

  const handleMouseLeave = () => {
    if (!isCollapsed) return;
    hoverTimeoutRef.current = window.setTimeout(() => {
      setHoveredFolder(null);
    }, 150);
  };

  const FloatingSubMenu = ({ folder }: { folder: { item: NavItem; top: number } }) => {
    const menuHeightEstimate = (folder.item.children?.length || 0) * 44 + 50;
    const viewportHeight = window.innerHeight;

    let adjustedTop = folder.top;
    if (adjustedTop + menuHeightEstimate > viewportHeight) {
      adjustedTop = Math.max(10, viewportHeight - menuHeightEstimate - 20);
    }

    return (
      <div 
        className="fixed left-[76px] z-[100] w-64 rounded-2xl border border-slate-800 bg-slate-900 shadow-2xl backdrop-blur-xl animate-in fade-in slide-in-from-left-2 duration-200 ring-1 ring-white/5"
        style={{ top: `${adjustedTop}px` }}
        onMouseEnter={() => {
          if (hoverTimeoutRef.current) window.clearTimeout(hoverTimeoutRef.current);
        }}
        onMouseLeave={handleMouseLeave}
      >
        <div className="mb-1 px-4 py-3 border-b border-slate-800/50 bg-slate-800/20 rounded-t-2xl">
          <p className="text-[10px] font-black uppercase tracking-widest text-indigo-400">{folder.item.label}</p>
        </div>
        <div className="p-1.5 space-y-1">
          {folder.item.children?.map(child => (
            <button
              key={child.id}
              onClick={() => {
                onViewChange(child.id as ActiveView);
                setHoveredFolder(null);
                if (window.innerWidth < 768) onClose();
              }}
              className={`w-full rounded-xl px-4 py-2 text-left text-sm font-semibold transition-all hover:bg-slate-800/80 ${
                activeView === child.id ? 'bg-indigo-600/15 text-indigo-400' : 'text-slate-400 hover:text-white'
              }`}
            >
              {child.label}
            </button>
          ))}
        </div>
      </div>
    );
  };

  const renderItem = (item: NavItem, level = 0) => {
    const isExpanded = expandedFolders.includes(item.id);
    const isActive = activeView === item.id || (item.children?.some(c => c.id === activeView));
    const hasChildren = !!item.children?.length;

    return (
      <div 
        key={item.id} 
        className="relative w-full"
        onMouseEnter={(e) => handleMouseEnter(item, e)}
        onMouseLeave={handleMouseLeave}
      >
        <button
          onClick={(e) => handleItemClick(item, e)}
          className={`group relative flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold transition-all duration-300 ${
            isActive && !hasChildren
              ? 'bg-indigo-600/10 text-indigo-400 ring-1 ring-inset ring-indigo-500/30' 
              : isActive && hasChildren 
              ? 'text-indigo-400'
              : 'text-slate-400 hover:bg-slate-800/40 hover:text-slate-200'
          } ${level > 0 ? 'ml-4' : ''}`}
        >
          {item.icon && (
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 shrink-0 ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-slate-300'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              {item.icon}
            </svg>
          )}

          {(!isCollapsed || level > 0) && (
            <span className="flex-1 text-left truncate tracking-tight">{item.label}</span>
          )}

          {hasChildren && !isCollapsed && (
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transition-transform ${isExpanded ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
            </svg>
          )}
        </button>

        {hasChildren && isExpanded && !isCollapsed && (
          <div className="mt-1 space-y-1 border-l border-slate-800 ml-5 pl-1.5">
            {item.children?.map(child => renderItem(child, level + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <>
      {isOpen && (
        <div className="fixed inset-0 z-40 bg-slate-950/70 backdrop-blur-md md:hidden" onClick={onClose} />
      )}

      {isCollapsed && hoveredFolder && (
        <FloatingSubMenu folder={hoveredFolder} />
      )}

      <aside className={`fixed inset-y-0 left-0 z-50 flex flex-col border-r border-slate-800 bg-slate-950/90 backdrop-blur-xl transition-all duration-500 md:static ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'} ${isCollapsed ? 'w-20' : 'w-72'}`}>

        <div className="flex h-16 items-center justify-between px-6 border-b border-slate-900">
          {!isCollapsed ? (
            <div className="flex items-center gap-2.5">
              <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.3)]">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
              </div>
              <span className="text-xl font-black text-white tracking-tighter">Vault<span className="text-indigo-500">Core</span></span>
            </div>
          ) : (
             <div className="mx-auto h-9 w-9 rounded-xl bg-indigo-600 flex items-center justify-center shadow-lg">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
             </div>
          )}

          <button onClick={() => setIsCollapsed(!isCollapsed)} className="hidden h-8 w-8 items-center justify-center rounded-lg text-slate-500 hover:bg-slate-800 md:flex">
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 transition-transform ${isCollapsed ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 19l-7-7 7-7m8 14l-7-7 7-7" />
            </svg>
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto p-4 space-y-8 no-scrollbar">
          {navigation.map((group, i) => (
            <div key={i} className="space-y-2">
              {!isCollapsed && <h5 className="px-3 text-[10px] font-black uppercase tracking-[0.2em] text-slate-600">{group.group}</h5>}
              <div className="space-y-1">{group.items.map(item => renderItem(item))}</div>
            </div>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-900 bg-slate-900/10">
          {!isCollapsed ? (
            <div className="flex items-center gap-3 rounded-2xl bg-slate-900/40 p-3 ring-1 ring-inset ring-slate-800/50">
              <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-indigo-600/10 text-indigo-400 font-black text-sm">
                {user?.username?.substring(0, 2).toUpperCase()}
              </div>
              <div className="flex-1 min-w-0">
                <p className="truncate text-sm font-bold text-white">{user?.username}</p>
                <p className="truncate text-[10px] font-bold text-slate-600 uppercase tracking-widest">Consultant</p>
              </div>
              <button onClick={logout} className="text-slate-600 hover:text-red-500 transition-colors p-1">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                </svg>
              </button>
            </div>
          ) : (
            <button onClick={logout} className="mx-auto flex h-10 w-10 items-center justify-center rounded-xl text-slate-600 hover:bg-red-500/10 hover:text-red-500">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
              </svg>
            </button>
          )}
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useEffect, useCallback } from 'react';
import { socketService } from '../services/socket';
import { INITIAL_METRICS } from '../constants';
import { AppState, Message, MetricData, ActiveView } from '../types';
import { usePWA } from '../hooks/usePWA';
import { useAuth } from '../auth/AuthContext';
import { useOffline } from '../hooks/useOffline';
import { api } from '../services/api';

import Sidebar from '../components/Sidebar';
import Header from '../components/Header';
import MetricCard from '../components/MetricCard';
import ChatPanel from '../components/ChatPanel';
import InstallBanner from '../components/InstallBanner';
import Loader from '../components/Loader';
import PageTemplate from './PageTemplate';

const Dashboard: React.FC = () => {
  const { user, token } = useAuth();
  const isOnline = useOffline();
  const [isDataLoading, setIsDataLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [state, setState] = useState<AppState>({
    messages: [],
    metrics: INITIAL_METRICS as MetricData[],
    users: [],
    isConnected: false,
    currentUser: user,
  });

  const [activeView, setActiveView] = useState<ActiveView>('dashboard');
  const { installPrompt, triggerInstall } = usePWA();

  useEffect(() => {
    const loadData = async () => {
      setIsDataLoading(true);
      try {
        const items = await api.get('/items');
        setState(prev => ({
          ...prev,
          metrics: prev.metrics.map(m => 
            m.label === 'Active Clients' ? { ...m, value: items.length || 0, trend: items.length > 0 ? 'up' : 'stable' } : m
          )
        }));
      } catch (err) {
        console.error('Failed to load dashboard data', err);
      } finally {
        setIsDataLoading(false);
      }
    };
    if (isOnline && token) loadData();
  }, [isOnline, token]);

  useEffect(() => {
    if (isOnline) {
      socketService.connect();
      socketService.on('db_item_change', (change: any) => {
        const itemCreator = change.data?.createdBy;
        const currentUserId = user?.id || (user as any)?._id;
        if (itemCreator === currentUserId) {
          if (change.type === 'insert') {
            setState(prev => ({
              ...prev,
              metrics: prev.metrics.map(m => 
                m.label === 'Active Clients' ? { ...m, value: m.value + 1, trend: 'up' } : m
              )
            }));
          }
        }
      });
      socketService.on('message', (msg: Message) => {
        setState(prev => {
          if (prev.messages.find(m => m.id === msg.id)) return prev;
          return { ...prev, messages: [...prev.messages, msg] };
        });
      });
      setState(prev => ({ ...prev, isConnected: true }));
    } else {
      socketService.disconnect();
      setState(prev => ({ ...prev, isConnected: false }));
    }
    return () => { socketService.disconnect(); };
  }, [isOnline, user]);

  const handleSendMessage = useCallback(async (content: string) => {
    const newMessage: Message = {
      id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      sender: user?.username || 'User',
      content,
      timestamp: Date.now(),
    };
    setState(prev => ({ ...prev, messages: [...prev.messages, newMessage] }));
    socketService.emit('message', newMessage);
  }, [user]);

  if (isDataLoading) return <Loader />;

  const renderContent = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <div className="max-w-7xl mx-auto space-y-6">
            <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
              {state.metrics.map((metric, idx) => <MetricCard key={idx} metric={metric} />)}
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-2 rounded-2xl bg-slate-900/50 p-6 border border-slate-800 backdrop-blur-sm shadow-xl">
                <div className="flex items-center justify-between mb-6">
                  <div>
                    <h3 className="text-lg font-semibold text-slate-300">Your Client Activity</h3>
                    <p className="text-xs text-slate-500">Real-time stats for your consulting firm</p>
                  </div>
                  <div className="flex items-center gap-2">
                     <div className="h-2 w-2 rounded-full bg-green-500 animate-pulse" />
                     <span className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">Live Sync</span>
                  </div>
                </div>
                <div className="h-64 w-full flex items-end justify-between gap-2 px-2">
                   {[...Array(15)].map((_, i) => (
                     <div key={i} className="flex flex-col items-center flex-1">
                        <div 
                          className={`w-full ${isOnline ? 'bg-indigo-500/30 hover:bg-indigo-500/50' : 'bg-slate-700/20'} rounded-t-lg transition-all duration-700 ease-in-out`} 
                          style={{ height: `${Math.max(10, Math.sin((i + Date.now()/10000)) * 30 + 50)}%` }} 
                        />
                     </div>
                   ))}
                </div>
              </div>
              <div className="rounded-2xl bg-slate-900/50 p-6 border border-slate-800 backdrop-blur-sm shadow-xl">
                <h3 className="mb-4 text-lg font-semibold text-slate-300">Recent Firm Events</h3>
                <div className="space-y-4">
                  {state.messages.slice(-3).reverse().map((msg, i) => (
                    <div key={i} className="flex items-center justify-between p-3 rounded-xl bg-slate-800/40 border border-slate-700/50">
                      <div className="flex-1 truncate pr-2">
                        <p className="text-sm font-bold text-slate-200 truncate">{msg.content}</p>
                        <p className="text-[10px] text-slate-500 font-medium">Synced by {msg.sender}</p>
                      </div>
                      <div className="h-2 w-2 rounded-full bg-indigo-500" />
                    </div>
                  ))}
                  {state.messages.length === 0 && <p className="text-xs text-slate-500 italic text-center py-4">No recent activity.</p>}
                </div>
              </div>
            </div>
          </div>
        );
      case 'messenger':
        return <ChatPanel messages={state.messages} onSend={handleSendMessage} currentUser={user} />;

      // Client Hub
      case 'gst-portfolio': return <PageTemplate title="GST Portfolio" description="Comprehensive list of clients and their GST portal status." />;
      case 'it-portfolio': return <PageTemplate title="IT Portfolio" description="Income Tax profiles and filing history for all registered clients." />;

      // Compliance - GST Return
      case 'compliance-monthly': return <PageTemplate title="Monthly Filing" description="Track and manage monthly GSTR-1 and GSTR-3B compliance." />;
      case 'compliance-quarterly': return <PageTemplate title="Quarterly Filing" description="QRMP scheme management and quarterly return status." />;
      case 'compliance-composition': return <PageTemplate title="Composition Filing" description="Quarterly CMP-08 and annual GSTR-4 filing for composition taxpayers." />;

      // Compliance - Annual Returns
      case 'compliance-gstr4': return <PageTemplate title="GSTR-4" description="Annual return management for composition dealers." />;
      case 'compliance-gstr9': return <PageTemplate title="GSTR-9/9C" description="Annual return and reconciliation statements for regular taxpayers." />;

      // Compliance - IT & Audit
      case 'compliance-itr': return <PageTemplate title="ITR Returns" description="Manage Income Tax Return filings for Individuals, Firms, and Companies." />;
      case 'compliance-taxaudit': return <PageTemplate title="Tax Audits" description="Audit reports and documentation under Section 44AB." />;
      case 'compliance-balancesheets': return <PageTemplate title="Balance Sheets" description="Financial statement generation and archival for clients." />;

      // Litigation Suite - Notices
      case 'lit-notice-pending': return <PageTemplate title="Pending GST Notices" description="List of notices awaiting professional response or client documentation." />;
      case 'lit-notice-filed': return <PageTemplate title="Filed Notices" description="Archive of notice replies successfully submitted to the department." />;
      case 'lit-notice-drop': return <PageTemplate title="Drop Orders" description="Notices that have been dropped or proceedings closed by the officer." />;
      case 'lit-notice-demand': return <PageTemplate title="Demand Orders" description="Notices resulting in an confirmed tax, interest, or penalty demand." />;

      // Litigation Suite - Appeals
      case 'lit-appeal-pending': return <PageTemplate title="Pending Appeals" description="First Appeals currently in progress before the Commissioner (Appeals)." />;
      case 'lit-appeal-filed': return <PageTemplate title="Filed Appeals" description="Record of Form GST APL-01 filings and hearing schedules." />;
      case 'lit-appeal-drop': return <PageTemplate title="Appeal Drop" description="Appeals concluded with favorable orders for the client." />;
      case 'lit-appeal-demand': return <PageTemplate title="Appeal Demand" description="Appeals resulting in sustained tax demands." />;

      // Tribunal & High Court
      case 'lit-tribunal-pending': return <PageTemplate title="Tribunal Pending" description="Matters pending before GSTAT (Tribunal)." />;
      case 'lit-tribunal-filed': return <PageTemplate title="Tribunal Filed" description="Appeals filed before the Tribunal." />;
      case 'lit-tribunal-drop': return <PageTemplate title="Tribunal Drop" description="Tribunal orders dismissing department demands." />;
      case 'lit-tribunal-demand': return <PageTemplate title="Tribunal Demand" description="Confirmed demands at the Tribunal level." />;
      case 'lit-hc-pending': return <PageTemplate title="High Court Pending" description="Writ petitions and Tax Appeals pending before the High Court." />;
      case 'lit-hc-filed': return <PageTemplate title="High Court Filed" description="Documentation of filings in High Court jurisdictions." />;
      case 'lit-hc-drop': return <PageTemplate title="High Court Drop" description="Favorable judgments from the High Court." />;
      case 'lit-hc-demand': return <PageTemplate title="High Court Demand" description="Sustained demands after High Court proceedings." />;

      // Miscellaneous
      case 'misc-gst-reg': return <PageTemplate title="GST Registration" description="New registrations, amendments, and cancellations of GST certificates." />;
      case 'misc-food-lic': return <PageTemplate title="Food Licenses" description="FSSAI registration and license management." />;
      case 'misc-msme': return <PageTemplate title="MSME Registration" description="Udyam registration and certificate lifecycle management." />;
      case 'misc-work': return <PageTemplate title="Miscellaneous Work" description="Other consulting services including PAN, TAN, and DSC." />;

      // Administration
      case 'reminders': return <PageTemplate title="Reminders" description="Set up automated alerts for client document submission and filing dates." />;
      case 'admin-invoices': return <PageTemplate title="Client Invoices" description="Professional billing for consulting services provided." />;
      case 'admin-payments': return <PageTemplate title="Payment Received" description="Track professional fees received and outstanding client balances." />;
      case 'admin-duedates': return <PageTemplate title="Due Date Setting" description="Configure custom compliance calendars for the firm." />;
      case 'settings': return <PageTemplate title="Settings" description="Configure firm profile, user permissions, and security parameters." />;
      case 'trash': return <PageTemplate title="Trash" description="Recently deleted client data and documents (30-day retention)." />;

      default: return <PageTemplate title="Module Placeholder" description="This feature is coming soon to the VaultCore dashboard." />;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-100">
      <Sidebar activeView={activeView} onViewChange={setActiveView} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />
      <main className="flex flex-1 flex-col overflow-hidden relative">
        <Header isConnected={state.isConnected && isOnline} currentUser={user} onMenuClick={() => setIsSidebarOpen(true)} />
        <div className="flex-1 overflow-y-auto p-4 md:p-8 no-scrollbar">
          {installPrompt && <InstallBanner onInstall={triggerInstall} />}
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../auth/AuthContext';
import { ActiveView } from '../types';

interface NavItem {
  id: ActiveView | string;
  label: string;
  icon?: React.ReactNode;
  children?: NavItem[];
}

interface SidebarProps {
  activeView: ActiveView;
  onViewChange: (view: ActiveView) => void;
  isOpen: boolean;
  onClose: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, onViewChange, isOpen, onClose }) => {
  const { logout, user } = useAuth();
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [expandedFolders, setExpandedFolders] = useState<string[]>([]);
  const [hoveredFolder, setHoveredFolder] = useState<{ item: NavItem; top: number } | null>(null);
  const hoverTimeoutRef = useRef<number | null>(null);

  const navigation: { group: string; items: NavItem[] }[] = [
    {
