    } else {
      onViewChange(item.id as ActiveView);
      if (window.innerWidth < 768) onClose();
    }
  };

  const renderItem = (item: NavItem, level = 0) => {
    const isExpanded = expandedFolders.includes(item.id);
    const isActive = activeView === item.id;
    const hasChildren = !!item.children?.length;

    return (
      <div key={item.id} className="w-full">
        <button
          onClick={(e) => handleItemClick(item, e)}
          className={`group flex w-full items-center gap-4 rounded-2xl px-4 py-3 text-base font-bold transition-all duration-200 ${
            isActive ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900'
          } ${level > 0 ? 'ml-6' : ''}`}
        >
          {item.icon && (
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 shrink-0 ${isActive ? 'text-white' : 'text-slate-400 group-hover:text-slate-600'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              {item.icon}
            </svg>
