          <span className="flex-1 text-left truncate">{item.label}</span>
          {hasChildren && (
            <svg xmlns="http://www.w3.org/2000/svg" className={`h-5 w-5 transition-transform ${isExpanded ? 'rotate-90' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
            </svg>
          )}
        </button>
        {hasChildren && isExpanded && (
          <div className="mt-1 space-y-1 border-l-2 border-slate-100 ml-6 pl-2">
            {item.children?.map(child => renderItem(child, level + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <>
      {isOpen && <div className="fixed inset-0 z-40 bg-slate-900/20 backdrop-blur-sm md:hidden" onClick={onClose} />}
      <aside className={`fixed inset-y-0 left-0 z-50 flex flex-col border-r border-slate-200 bg-white shadow-2xl transition-all duration-300 md:static ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'} ${isCollapsed ? 'w-20' : 'w-80'}`}>
        <div className="flex h-20 items-center justify-between px-6 border-b border-slate-100">
           <div className="flex items-center gap-3">
             <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-600 text-white shadow-md">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
             {!isCollapsed && <span className="text-2xl font-black text-slate-900 tracking-tight">Vault<span className="text-indigo-600">Core</span></span>}
           </div>
        </div>
        <nav className="flex-1 overflow-y-auto p-4 space-y-8 no-scrollbar">
          {navigation.map((group, i) => (
            <div key={i} className="space-y-3">
              {!isCollapsed && <h5 className="px-4 text-xs font-black uppercase tracking-widest text-slate-400">{group.group}</h5>}
              <div className="space-y-1">{group.items.map(item => renderItem(item))}</div>
            </div>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-100">
          <button onClick={logout} className="flex w-full items-center gap-4 rounded-2xl bg-slate-50 p-4 text-slate-600 hover:bg-red-50 hover:text-red-600 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            {!isCollapsed && <span className="font-bold">Logout Session</span>}
          </button>
        </div>
      </aside>
    </>
  );
};

