const QuarterlyFiling = lazy(() => import('./Compliance/GSTReturn/QuarterlyFiling'));
const CompositionFiling = lazy(() => import('./Compliance/GSTReturn/CompositionFiling'));

const Dashboard: React.FC = () => {
  const { user, token } = useAuth();
  const isOnline = useOffline();
  const [isDataLoading, setIsDataLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [state, setState] = useState<AppState>({
    messages: [],
    metrics: INITIAL_METRICS as MetricData[],
    users: [],
    isConnected: false,
    currentUser: user,
  });

  const [activeView, setActiveView] = useState<ActiveView>('dashboard');
  const { installPrompt, triggerInstall } = usePWA();

  useEffect(() => {
    const loadData = async () => {
      setIsDataLoading(true);
      try {
        const items = await api.get('/items');
        setState(prev => ({
          ...prev,
          metrics: prev.metrics.map(m => 
            m.label === 'Active Clients' ? { ...m, value: items.length || 0, trend: items.length > 0 ? 'up' : 'stable' } : m
          )
        }));
      } catch (err) {
        console.error('Failed to load dashboard data', err);
      } finally {
        setIsDataLoading(false);
      }
    };
    if (isOnline && token) loadData();
  }, [isOnline, token]);

  useEffect(() => {
    if (isOnline) {
      socketService.connect();
      socketService.on('message', (msg: Message) => {
        setState(prev => ({ ...prev, messages: [...prev.messages, msg] }));
      });
      setState(prev => ({ ...prev, isConnected: true }));
    } else {
      socketService.disconnect();
      setState(prev => ({ ...prev, isConnected: false }));
    }
    return () => { socketService.disconnect(); };
  }, [isOnline]);

  const handleSendMessage = useCallback(async (content: string) => {
    const newMessage: Message = {
      id: `msg_${Date.now()}`,
      sender: user?.username || 'Consultant',
      content,
      timestamp: Date.now(),
    };
    setState(prev => ({ ...prev, messages: [...prev.messages, newMessage] }));
    socketService.emit('message', newMessage);
  }, [user]);

  if (isDataLoading) return <Loader />;

  const renderContent = () => {
    return (
      <Suspense fallback={<Loader />}>
        {(() => {
          switch (activeView) {
            case 'dashboard':
              return (
                <div className="max-w-7xl mx-auto space-y-10 animate-in fade-in duration-500">
                  <div className="grid grid-cols-1 gap-8 sm:grid-cols-2 lg:grid-cols-4">
                    {state.metrics.map((metric, idx) => <MetricCard key={idx} metric={metric} />)}
                  </div>
                  <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <div className="lg:col-span-2 rounded-3xl bg-white p-10 border border-slate-200 shadow-sm">
                      <div className="flex items-center justify-between mb-8">
                        <div>
                          <h3 className="text-2xl font-black text-slate-900">Firm Overview</h3>
                          <p className="text-lg text-slate-500">Real-time status of current client projects</p>
                        </div>
                      </div>
                      <div className="h-80 w-full flex items-end justify-between gap-4">
                         {[...Array(10)].map((_, i) => (
                           <div key={i} className="flex-1 bg-indigo-50 rounded-2xl relative group hover:bg-indigo-100 transition-colors" style={{ height: `${20 + (i * 8)}%` }}>
                              <div className="absolute inset-x-0 bottom-0 bg-indigo-600 rounded-2xl transition-all duration-700 h-1/2 group-hover:h-3/4" />
                           </div>
                         ))}
                      </div>
                    </div>
                    <div className="rounded-3xl bg-white p-10 border border-slate-200 shadow-sm overflow-hidden">
                      <h3 className="mb-6 text-2xl font-black text-slate-900">Communication</h3>
                      <div className="space-y-6">
                        {state.messages.slice(-4).reverse().map((msg, i) => (
                          <div key={i} className="p-4 rounded-2xl bg-slate-50 border border-slate-100">
                            <p className="text-lg font-bold text-slate-900">{msg.content}</p>
                            <p className="text-xs font-black text-indigo-600 uppercase tracking-widest mt-1">{msg.sender}</p>
                          </div>
                        ))}
                        {state.messages.length === 0 && <p className="text-slate-400 italic">No recent broadcasts.</p>}
                      </div>
                    </div>
                  </div>
                </div>
              );
            case 'gst-portfolio': return <GSTPortfolio />;
            case 'it-portfolio': return <ITPortfolio />;
            case 'compliance-monthly': return <MonthlyFiling />;
            case 'compliance-quarterly': return <QuarterlyFiling />;
            case 'compliance-composition': return <CompositionFiling />;
            case 'messenger': return <ChatPanel messages={state.messages} onSend={handleSendMessage} currentUser={user} />;
            default: return (
              <div className="text-center py-20 bg-white rounded-3xl border border-slate-200">
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Module Initialization</h3>
                <p className="text-slate-500 text-lg mt-2">Connecting to secure storage for {activeView}...</p>
              </div>
            );
          }
        })()}
      </Suspense>
    );
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-50 text-slate-900">
      <Sidebar activeView={activeView} onViewChange={setActiveView} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} />
      <main className="flex flex-1 flex-col overflow-hidden relative">
        <Header isConnected={state.isConnected} currentUser={user} onMenuClick={() => setIsSidebarOpen(true)} />
        <div className="flex-1 overflow-y-auto p-6 md:p-12 no-scrollbar">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useCallback } from 'react';
import { AuthProvider, useAuth } from './auth/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import Navbar from './components/Navbar';
import Home from './pages/Home';
import Dashboard from './pages/Primary/Dashboard';
import Login from './auth/Login';
import Signup from './auth/Signup';
import Loader from './components/Loader';
import OfflineBanner from './components/OfflineBanner';
import { api } from './services/api';
import { useOffline } from './hooks/useOffline';

type Page = 'home' | 'login' | 'signup' | 'dashboard';

const AppContent: React.FC = () => {
  const { isAuthenticated, token, hasCheckedAuth, isLoading } = useAuth();
  const [currentPage, setCurrentPage] = useState<Page>('home');

  const handleReconnect = useCallback(() => {
    if (token) {
      api.get('/auth/me').catch(console.error);
    }
  }, [token]);

  const isOnline = useOffline(handleReconnect);

  useEffect(() => {
    if (!hasCheckedAuth) return;
    if (isAuthenticated) {
      if (currentPage !== 'dashboard') setCurrentPage('dashboard');
    } else {
      if (currentPage === 'dashboard') setCurrentPage('home');
    }
  }, [isAuthenticated, hasCheckedAuth]);

  if (!hasCheckedAuth) return <Loader />;

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return (
          <>
            <Navbar onLoginClick={() => setCurrentPage('login')} onHomeClick={() => setCurrentPage('home')} />
            <Home onGetStarted={() => setCurrentPage('signup')} />
          </>
        );
      case 'login':
        return <Login onSwitch={() => setCurrentPage('signup')} onBackToHome={() => setCurrentPage('home')} />;
      case 'signup':
        return <Signup onSwitch={() => setCurrentPage('login')} onBackToHome={() => setCurrentPage('home')} />;
      case 'dashboard':
        return (
          <ProtectedRoute fallback={<Login onSwitch={() => setCurrentPage('signup')} onBackToHome={() => setCurrentPage('home')} />}>
            <Dashboard />
          </ProtectedRoute>
        );
      default:
        return <Home onGetStarted={() => setCurrentPage('signup')} />;
    }
  };

  return (
    <>
      <OfflineBanner isOnline={isOnline} />
      {renderPage()}
      {isLoading && <div className="fixed inset-0 z-[9999] bg-slate-950/20 backdrop-blur-sm"><Loader /></div>}
    </>
  );
};

const App: React.FC = () => (
  <AuthProvider>
    <AppContent />
  </AuthProvider>
);

export default App;

