// LAZY IMPORTS FOR ALL MODULES - Using renamed folders without spaces or symbols
const GSTPortfolio = lazy(() => import('../ClientHub/GSTPortfolio'));
const ITPortfolio = lazy(() => import('../ClientHub/ITPortfolio'));

