import { io, Socket } from 'socket.io-client';
import { SOCKET_URL } from '../constants';

// Removed non-existent SocketEvent import to resolve type error

class SocketService {
  private socket: Socket | null = null;

  connect() {
    // If it's a mock or example URL, we just log it for the demo
    if (SOCKET_URL.includes('example.com')) {
        console.warn('SocketService: Using simulated real-time events.');
        return;
    }

    try {
      this.socket = io(SOCKET_URL, {
        transports: ['websocket'],
        reconnectionAttempts: 5,
      });

      this.socket.on('connect_error', (err) => {
        console.warn('Socket connection failed, likely backend is offline. Using simulation mode.');
      });
    } catch (e) {
      console.error('Socket init failed', e);
    }
  }

  on(event: string, callback: (data: any) => void) {
    this.socket?.on(event, callback);
  }

  emit(event: string, data: any) {
    this.socket?.emit(event, data);
  }

  disconnect() {
    this.socket?.disconnect();
  }
}

export const socketService = new SocketService();

import { User, Client, ClientStatus } from '../types';

class MockBackend {
  private STORAGE_KEY_USERS = 'clientify_mock_users';
  private STORAGE_KEY_CLIENTS = 'clientify_mock_clients';
  private STORAGE_KEY_ITEMS = 'clientify_mock_items';

  constructor() {
    if (!localStorage.getItem(this.STORAGE_KEY_USERS)) {
      const defaultUsers = [
        { id: 'mock_1', username: 'Demo CA', user_id: 'admin', password: 'password', email_id: 'demo@vaultcore.com', status: 'online' },
        { id: 'mock_test_a', username: 'Quick Tester', user_id: 'a', password: 'a', email_id: 'tester@vaultcore.com', status: 'online' }
      ];
      localStorage.setItem(this.STORAGE_KEY_USERS, JSON.stringify(defaultUsers));
    }
  }

  // Auth
  async signup(data: any) {
    const users = this.getUsers();
    if (users.find((u: any) => u.user_id === data.user_id)) throw new Error('User ID already taken');
    const newUser = { ...data, id: `u_${Date.now()}`, createdAt: Date.now(), status: 'online' };
    users.push(newUser);
    localStorage.setItem(this.STORAGE_KEY_USERS, JSON.stringify(users));
    return { token: 'mock_token_' + newUser.id, user: newUser };
  }

  async login(userId: string, pass: string) {
    const users = this.getUsers();
    const user = users.find((u: any) => u.user_id === userId && u.password === pass);
    if (!user) throw new Error('Invalid credentials');
    return { token: 'mock_token_' + user.id, user };
  }

  async me(token: string) {
    const userId = token.replace('mock_token_', '');
    const user = this.getUsers().find((u: any) => u.id === userId);
    if (!user) throw new Error('Session expired');
    return { user };
  }

  // Client Management
  async getClients(): Promise<Client[]> {
    return JSON.parse(localStorage.getItem(this.STORAGE_KEY_CLIENTS) || '[]');
  }

  async saveClient(clientData: Partial<Client>): Promise<Client> {
    const clients = await this.getClients();
    let client: Client;

    if (clientData.id) {
      const index = clients.findIndex(c => c.id === clientData.id);
      client = { ...clients[index], ...clientData } as Client;
      clients[index] = client;
    } else {
      client = {
        ...clientData,
        id: `c_${Date.now()}`,
        createdAt: Date.now(),
      } as Client;
      clients.push(client);
    }

    localStorage.setItem(this.STORAGE_KEY_CLIENTS, JSON.stringify(clients));
    return client;
  }

  async deleteClient(id: string): Promise<void> {
    const clients = await this.getClients();
    const filtered = clients.filter(c => c.id !== id);
    localStorage.setItem(this.STORAGE_KEY_CLIENTS, JSON.stringify(filtered));
  }

  // Merge Check: Extracts PAN from GSTIN (3rd to 12th char) or compares PAN directly
  async checkPanConflict(panOrGstin: string, currentClientId?: string): Promise<Client | null> {
    const clients = await this.getClients();
    const targetPan = panOrGstin.length === 15 ? panOrGstin.substring(2, 12) : panOrGstin;

    return clients.find(c => {
      if (c.id === currentClientId) return false;
      const existingPan = c.itProfile?.pan || c.gstProfile?.gstin.substring(2, 12);
      return existingPan?.toUpperCase() === targetPan.toUpperCase();
    }) || null;
  }

  // Items Management - Fixed: Added missing methods expected by api.ts
  async getItems(userId: string): Promise<any[]> {
    const items = JSON.parse(localStorage.getItem(this.STORAGE_KEY_ITEMS) || '[]');
    return items.filter((item: any) => item.createdBy === userId);
  }

  async createItem(userId: string, data: any): Promise<any> {
    const items = JSON.parse(localStorage.getItem(this.STORAGE_KEY_ITEMS) || '[]');
    const newItem = {
      ...data,
      id: `i_${Date.now()}`,
      createdBy: userId,
      createdAt: new Date().getTime()
    };
    items.push(newItem);
    localStorage.setItem(this.STORAGE_KEY_ITEMS, JSON.stringify(items));
    return newItem;
  }

  private getUsers() {
    return JSON.parse(localStorage.getItem(this.STORAGE_KEY_USERS) || '[]');
  }
}

