import React, { useState, useEffect, useMemo } from 'react';
import { Client } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import ClientFormModal from '../../components/ClientFormModal';
import Loader from '../../components/Loader';

interface MasterPortfolioProps {
  filter?: 'gst' | 'it';
}

const MasterPortfolio: React.FC<MasterPortfolioProps> = ({ filter }) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const fetchClients = async () => {
    setIsLoading(true);
    const data = await mockBackend.getClients();
    setClients(data);
    setIsLoading(false);
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const filteredClients = useMemo(() => {
    let list = clients;
    if (filter === 'gst') {
      list = list.filter(c => !!c.gstProfile);
    } else if (filter === 'it') {
      list = list.filter(c => !!c.itProfile);
    }

    const s = search.toLowerCase();
    return list.filter(c => 
      c.legalName.toLowerCase().includes(s) || 
      c.tradeName.toLowerCase().includes(s) || 
      c.gstProfile?.gstin.toLowerCase().includes(s) || 
      c.itProfile?.pan.toLowerCase().includes(s) ||
      c.mobile.includes(s)
    );
  }, [clients, search, filter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    setIsModalOpen(true);
  };

  const handleAddNew = () => {
    setSelectedClient(null);
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record? This will clear all GST and IT profiles associated with this legal entity.')) {
      await mockBackend.deleteClient(id);
      fetchClients();
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="max-w-7xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
        <div className="relative flex-1 max-w-xl group">
          <input 
            type="text" 
            placeholder="Search within this portfolio..."
            className="w-full bg-white border border-slate-200 rounded-3xl py-5 pl-14 pr-6 font-bold text-slate-900 shadow-sm focus:ring-4 focus:ring-indigo-50 transition-all outline-none"
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
          <svg className="absolute left-5 top-1/2 -translate-y-1/2 h-6 w-6 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
        {!filter && (
          <button 
            onClick={handleAddNew}
            className="bg-indigo-600 text-white font-black uppercase tracking-widest px-8 py-5 rounded-3xl shadow-xl shadow-indigo-100 hover:bg-slate-900 transition-all active:scale-95 flex items-center gap-3"
          >
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            Add Master Client
          </button>
        )}
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-6 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Legal Entity</th>
                <th className="px-8 py-6 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Identifiers</th>
                <th className="px-8 py-6 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Services</th>
                <th className="px-8 py-6 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.map((client) => (
                <tr key={client.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-8">
                    <p className="text-lg font-black text-slate-900 leading-tight">{client.legalName}</p>
                    <p className="text-sm font-bold text-slate-400 mt-1 uppercase tracking-tight">{client.tradeName || 'No Trade Name'}</p>
                    <div className="mt-3 flex items-center gap-2">
                       <span className={`h-2 w-2 rounded-full ${client.status.includes('Active') ? 'bg-green-500' : 'bg-slate-300'}`} />
                       <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{client.status}</span>
                    </div>
                  </td>
                  <td className="px-8 py-8">
                    <div className="space-y-3">
                      {client.gstProfile && (
