                        </div>
                      )}
                      {client.itProfile && (
                        <div className="flex items-center gap-2 group/id cursor-pointer" title="Click to copy PAN">
                           <div className="h-6 w-6 rounded-lg bg-emerald-50 flex items-center justify-center text-emerald-600 font-black text-[10px]">P</div>
                           <span className="text-xs font-bold text-slate-600 tracking-tighter font-mono">{client.itProfile.pan}</span>
