/**
 * MockBackend: A browser-based database simulator.
 * This allows testing the app without a running Node.js/MongoDB server.
 */
class MockBackend {
  private STORAGE_KEY_USERS = 'clientify_mock_users';
  private STORAGE_KEY_ITEMS = 'clientify_mock_items';
  private STORAGE_KEY_MESSAGES = 'clientify_mock_messages';
  private STORAGE_KEY_CLIENTS = 'clientify_mock_clients';

  constructor() {
    // Seed initial mock users if empty
    if (!localStorage.getItem(this.STORAGE_KEY_USERS)) {
      const defaultUsers = [
        { 
          id: 'mock_1', 
          username: 'Demo CA', 
          user_id: 'admin', 
          password: 'password', 
          email_id: 'demo@vaultcore.com', 
          status: 'online' 
        },
        { 
          id: 'mock_test_a', 
          username: 'Quick Tester', 
          user_id: 'a', 
          password: 'a', 
          email_id: 'tester@vaultcore.com', 
          status: 'online' 
        }
      ];
      localStorage.setItem(this.STORAGE_KEY_USERS, JSON.stringify(defaultUsers));
    } else {
      // If users exist but 'a' is missing, add it (for existing users who didn't clear localstorage)
      const users = JSON.parse(localStorage.getItem(this.STORAGE_KEY_USERS) || '[]');
      if (!users.find((u: any) => u.user_id === 'a')) {
        users.push({ 
          id: 'mock_test_a', 
          username: 'Quick Tester', 
          user_id: 'a', 
          password: 'a', 
          email_id: 'tester@vaultcore.com', 
          status: 'online' 
        });
        localStorage.setItem(this.STORAGE_KEY_USERS, JSON.stringify(users));
      }
    }

    // Initialize clients storage if empty
    if (!localStorage.getItem(this.STORAGE_KEY_CLIENTS)) {
      localStorage.setItem(this.STORAGE_KEY_CLIENTS, JSON.stringify([]));
    }
  }

  // --- Auth Simulation ---

  async signup(data: any) {
    const users = this.getUsers();
    if (users.find((u: any) => u.user_id === data.user_id)) {
      throw new Error('User ID already taken');
    }
    const newUser = { 
      ...data, 
      id: `u_${Date.now()}`, 
      _id: `u_${Date.now()}`, 
      createdAt: new Date(), 
      status: 'online' 
    };
    users.push(newUser);
    localStorage.setItem(this.STORAGE_KEY_USERS, JSON.stringify(users));
    return { token: 'mock_token_' + newUser.id, user: newUser };
  }

  async login(userId: string, pass: string) {
    const users = this.getUsers();
    const user = users.find((u: any) => u.user_id === userId && u.password === pass);
    if (!user) throw new Error('Invalid credentials');
    return { token: 'mock_token_' + user.id, user };
  }

  async me(token: string) {
    const userId = token.replace('mock_token_', '');
    const user = this.getUsers().find((u: any) => u.id === userId);
    if (!user) throw new Error('Session expired');
    return { user };
  }

  // --- Data Simulation ---

  async getItems(userId: string) {
    const items = this.getAllItems();
    return items.filter((i: any) => i.createdBy === userId);
  }

  async createItem(userId: string, itemData: any) {
    const items = this.getAllItems();
    const newItem = {
      _id: `item_${Date.now()}`,
      ...itemData,
      createdBy: userId,
      createdAt: new Date()
    };
    items.push(newItem);
    localStorage.setItem(this.STORAGE_KEY_ITEMS, JSON.stringify(items));
    return newItem;
  }

  // --- Client Simulation Methods ---

  /**
   * Fetches the full list of client records from local storage.
   */
  async getClients(): Promise<Client[]> {
    return JSON.parse(localStorage.getItem(this.STORAGE_KEY_CLIENTS) || '[]');
  }

  /**
   * Persists a client record. If an ID exists, it updates; otherwise, it creates a new entry.
   */
  async saveClient(data: Partial<Client>): Promise<Client> {
    const clients = await this.getClients();
    if (data.id) {
      const index = clients.findIndex((c: any) => c.id === data.id);
      if (index !== -1) {
        clients[index] = { ...clients[index], ...data };
        localStorage.setItem(this.STORAGE_KEY_CLIENTS, JSON.stringify(clients));
        return clients[index];
      }
    }
    const newClient = { ...data, id: `c_${Date.now()}` } as Client;
    clients.push(newClient);
    localStorage.setItem(this.STORAGE_KEY_CLIENTS, JSON.stringify(clients));
    return newClient;
  }

  /**
   * Removes a client record from the simulated database by its ID.
   */
  async deleteClient(id: string): Promise<void> {
    const clients = await this.getClients();
    const filtered = clients.filter((c: any) => c.id !== id);
    localStorage.setItem(this.STORAGE_KEY_CLIENTS, JSON.stringify(filtered));
  }

  /**
   * Validates if a PAN or GSTIN is already in use by another client.
   * Useful for preventing duplicate entities in the vault.
   */
  async checkPanConflict(val: string, excludeId?: string): Promise<Client | null> {
    const clients = await this.getClients();
    const match = clients.find((c: any) => 
      c.id !== excludeId && (
        (c.gstProfile?.gstin === val) || 
        (c.itProfile?.pan === val)
      )
    );
    return (match as Client) || null;
  }

  // --- Helpers ---

  private getUsers() {
    return JSON.parse(localStorage.getItem(this.STORAGE_KEY_USERS) || '[]');
  }

  private getAllItems() {
    return JSON.parse(localStorage.getItem(this.STORAGE_KEY_ITEMS) || '[]');
  }
}

export const mockBackend = new MockBackend();

