                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="space-y-2">
                        {client.gstProfile && (
                          <div className="flex items-center gap-2">
                             <div className="h-5 w-5 rounded-md bg-blue-50 flex items-center justify-center text-blue-600 font-black text-[10px]">G</div>
                             <span className="text-[11px] font-bold text-slate-600 font-mono uppercase">{client.gstProfile.gstin}</span>
