              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GSTIN</label>
              <div className="flex gap-2">
                <input className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3 font-black uppercase tracking-widest text-lg"
                  value={formData.gstProfile?.gstin} onChange={e => handleGstChange('gstin', e.target.value.toUpperCase())} placeholder="27XXXXX0000X1Z5" />
                <button 
                  onClick={() => copyAndOpen(formData.gstProfile?.gstin || '', 'https://services.gst.gov.in/services/searchtp')}
                  className="px-4 bg-indigo-50 text-indigo-600 rounded-xl border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all"
                  title="Verify GSTIN"
                >
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </button>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Portal Login ID</label>
              <div className="flex gap-2">
                <input className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.username} onChange={e => handleGstChange('username', e.target.value)} />
                <button 
                  onClick={() => copyAndOpen(formData.gstProfile?.username || '', 'https://services.gst.gov.in/services/login')}
                  className="px-4 bg-slate-900 text-white rounded-xl hover:bg-indigo-600 transition-all font-black text-[10px] uppercase"
                >
                  Login
                </button>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Portal Password</label>
              <div className="relative">
                <input type={showPassword ? "text" : "password"} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.password} onChange={e => handleGstChange('password', e.target.value)} />
                <button onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3 text-slate-400 hover:text-indigo-600">
                  {showPassword ? (
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>
                  ) : (
                    <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 12z" /></svg>
