                <h4 className="text-xs font-black uppercase tracking-widest text-slate-500">
                  {formData.gstProfile?.constitution === 'Proprietorship' ? 'Proprietor Details' : 
                   formData.gstProfile?.constitution === 'Partnership' ? 'Partner Details' :
                   formData.gstProfile?.constitution === 'HUF' ? 'Member Details' : 'Director Details'}
                </h4>
                {formData.gstProfile?.constitution !== 'Proprietorship' && (
                  <button onClick={addStakeholder} className="text-[10px] font-black uppercase bg-indigo-600 text-white px-3 py-1.5 rounded-lg shadow-sm">+ Add</button>
