const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [showImportOptions, setShowImportOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const load = async () => {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    };
    load();
  }, [refreshTrigger]);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  const handleExportCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Status", "Reg Type", "Filing Freq", "Constitution"];
    const rows = clients.map(c => [
      c.legalName,
      c.tradeName,
      c.mobile,
      c.gstProfile?.gstin,
      c.status,
      c.gstProfile?.regType,
      c.gstProfile?.filingFreq,
      c.gstProfile?.constitution
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_clients_export.csv");
    link.click();
  };

  const handleImportTemplateCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Portal ID", "Password", "Status", "Reg Type", "Filing Freq", "Constitution"];
    const example = ["Clientify Demo Ltd", "Clientify", "9876543210", "27AAAAA0000A1Z5", "user123", "pass123", "Active Filing", "Regular", "Monthly", "Proprietorship"];
    const csvContent = [headers, example].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_import_template.csv");
    link.click();
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1); // skip header
      let successCount = 0;
      let duplicateCount = 0;

      for (const row of rows) {
        const cols = row.split(',');
        if (cols.length < 4) continue;

        const gstin = cols[3]?.trim();
        if (!gstin) continue;

        try {
          await mockBackend.saveClient({
            legalName: cols[0]?.trim(),
            tradeName: cols[1]?.trim(),
            mobile: cols[2]?.trim(),
            status: (cols[6]?.trim() as any) || 'Active Filing',
            gstProfile: {
              gstin,
              username: cols[4]?.trim() || '',
              password: cols[5]?.trim() || '',
              gstStatus: 'Active',
              regDate: new Date().toISOString().split('T')[0],
              regType: (cols[7]?.trim() as any) || 'Regular',
              filingFreq: (cols[8]?.trim() as any) || 'Monthly',
              constitution: (cols[9]?.trim() as any) || 'Proprietorship',
              stakeholders: []
            }
          });
          successCount++;
        } catch (err: any) {
          if (err.message.includes('already exists')) duplicateCount++;
        }
      }
      alert(`Import complete: ${successCount} added, ${duplicateCount} duplicates skipped.`);
      setRefreshTrigger(p => p + 1);
      setShowImportOptions(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="flex flex-col h-full space-y-4 pb-4 overflow-hidden">
      {/* Search Header Area */}
      <div className="shrink-0 group w-full">
