            value={search}
            onChange={e => setSearch(e.target.value)}
          />
          <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
      </div>

      {/* Stats and Actions Line */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 shrink-0 bg-white p-4 rounded-3xl border border-slate-100 shadow-sm">
        {/* Status Indicators */}
        <div className="flex items-center gap-6 px-4">
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Total Clients</span>
            <span className="text-xl font-black text-slate-900">{stats.total}</span>
          </div>
          <div className="h-8 w-[1px] bg-slate-100" />
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase text-green-500 tracking-widest">Active</span>
            <span className="text-xl font-black text-green-600">{stats.active}</span>
          </div>
          <div className="h-8 w-[1px] bg-slate-100" />
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase text-amber-500 tracking-widest">Case</span>
            <span className="text-xl font-black text-amber-600">{stats.caseStudy}</span>
          </div>
          <div className="h-8 w-[1px] bg-slate-100" />
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase text-red-400 tracking-widest">Inactive</span>
            <span className="text-xl font-black text-red-500">{stats.inactive}</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {/* Import Button */}
          <div className="relative">
            <button 
              onClick={() => setShowImportOptions(!showImportOptions)}
              className="h-12 w-12 flex items-center justify-center bg-white border border-slate-200 rounded-xl text-slate-600 hover:text-indigo-600 hover:border-indigo-200 transition-all"
              title="Import CSV"
            >
              <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0l-4-4m4 4v12" /></svg>
            </button>
            {showImportOptions && (
              <div className="absolute right-0 mt-2 w-56 bg-white border border-slate-200 rounded-xl shadow-xl z-50 p-2 animate-in fade-in slide-in-from-top-2">
                <button onClick={handleImportTemplateCSV} className="w-full text-left px-4 py-2 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-lg">Download CSV Template</button>
                <label className="w-full block px-4 py-2 text-[10px] font-black uppercase tracking-widest text-indigo-600 hover:bg-slate-50 rounded-lg cursor-pointer">
                  Upload CSV File
                  <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
                </label>
              </div>
            )}
          </div>

          {/* Export Button */}
          <button 
            onClick={handleExportCSV}
            className="h-12 w-12 flex items-center justify-center bg-white border border-slate-200 rounded-xl text-slate-600 hover:text-indigo-600 hover:border-indigo-200 transition-all"
            title="Export CSV"
          >
            <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>

          {/* Add GST Client Button */}
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-indigo-600 text-white font-black uppercase tracking-tight px-6 h-12 rounded-xl shadow-lg hover:bg-slate-900 transition-all active:scale-95 flex items-center justify-center gap-2 shrink-0 text-xl"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
            Add GST Client
          </button>
        </div>
      </div>

      {/* Main Table Content */}
      <div className="flex-1 min-h-0 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <MasterPortfolio 
          key={refreshTrigger} 
          filter="gst" 
          externalSearch={search}
          hideInternalSearch={true}
        />
      </div>

      <GSTClientFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={() => setRefreshTrigger(prev => prev + 1)} 
      />
    </div>
  );
};

