          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Accountant Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.gstProfile?.accountantName} onChange={e => handleGstChange('accountantName', e.target.value)} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Accountant Mobile</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.gstProfile?.accountantMobile} onChange={e => handleGstChange('accountantMobile', e.target.value)} />
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: Banking */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Bank Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.bankDetails?.bankName} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, bankName: e.target.value}})} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Account No</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.bankDetails?.accountNo} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, accountNo: e.target.value}})} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">IFSC Code</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold uppercase"
                value={formData.bankDetails?.ifsc} onChange={e => setFormData({...formData, bankDetails: {...formData.bankDetails!, ifsc: e.target.value}})} />
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Section: Misc */}
          <div className="space-y-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Address</label>
              <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold h-24"
                value={formData.gstProfile?.address} onChange={e => handleGstChange('address', e.target.value)} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GST Certificate (Upload PDF)</label>
              <div className="flex items-center gap-3 bg-slate-50 border border-slate-200 rounded-xl p-3">
                 <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-900 hover:text-white transition-all shadow-sm"
                 >
                   <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                   Select PDF
                 </button>
                 <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileUpload} />
                 <span className="text-xs font-bold text-slate-500 truncate">{formData.gstProfile?.certificateUrl || 'No file selected'}</span>
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Internal Remarks</label>
              <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold h-24"
                value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} />
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="p-8 border-t border-slate-100 flex gap-4 shrink-0 bg-slate-50/50">
          <button onClick={onClose} className="flex-1 py-4 rounded-xl text-slate-500 font-black uppercase tracking-widest hover:bg-slate-100 transition-all border border-slate-200 text-xs">Cancel</button>
          <button onClick={handleSave} className="flex-[2] bg-indigo-600 text-white font-black uppercase tracking-widest py-4 rounded-xl shadow-xl shadow-indigo-100 hover:bg-slate-900 transition-all active:scale-95 text-xs">
            {initialData ? 'Update Record' : 'Register GST Client'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default GSTClientFormModal;

export interface Message {
  id: string;
  sender: string;
  content: string;
  timestamp: number;
}

export interface MetricData {
  label: string;
  value: number;
  trend: 'up' | 'down' | 'stable';
}

export interface User {
  id: string;
  username: string;
  user_id: string;
  email_id: string;
  mobile_no?: string;
  firm_name?: string | null;
  gstn?: string | null;
  status: 'online' | 'away' | 'offline';
}

export interface AppState {
  messages: Message[];
  metrics: MetricData[];
  users: User[];
  isConnected: boolean;
  currentUser: User | null;
}

export type ActiveView = string;

export type ClientStatus = 'Active Filing' | 'Case-by-Case' | 'Inactive (Temporary)' | 'Inactive (Closed)';
export type GstStatus = 'Active' | 'Suspended' | 'Cancelled';
export type GstRegType = 'Regular' | 'Composition';
export type GstFilingFreq = 'Monthly' | 'Quarterly';
export type ConstitutionType = 'Proprietorship' | 'Partnership' | 'HUF' | 'Company' | 'Trust' | 'Other';
export type JurisdictionType = 'Center' | 'State';
export type ClientService = 'IT Return' | 'Audit' | 'Notice handling' | 'MSME' | 'Food License';

export interface Stakeholder {
  id: string;
  name: string;
  mobile: string;
  pan: string;
}

export interface GSTProfile {
  gstin: string;
  username: string;
  password?: string;
  gstStatus: GstStatus;
  regDate: string;
  cancelDate?: string;
  regType: GstRegType;
  filingFreq: GstFilingFreq;
  constitution: ConstitutionType;
  stakeholders: Stakeholder[];
  accountantName?: string;
  accountantMobile?: string;
  certificateUrl?: string;
  address?: string;
  jurisdictionType?: JurisdictionType;
  sector?: string;
  range?: string;
}

export interface ITProfile {
  pan: string;
  category: string;
  username: string;
  password?: string;
}

export interface BankDetails {
  bankName: string;
  accountNo: string;
  ifsc: string;
}

export interface Client {
  id: string;
  legalName: string;
  tradeName: string;
  mobile: string;
  email: string;
  status: ClientStatus;
  gstProfile?: GSTProfile;
  itProfile?: ITProfile;
  services?: ClientService[];
  bankDetails?: BankDetails;
  remarks?: string;
  createdAt: number;
}

import React, { useState, useEffect, useRef } from 'react';
import { Client, GSTProfile, Stakeholder, ConstitutionType, GstStatus, GstRegType, GstFilingFreq, ClientStatus, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';

interface GSTClientFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (client: Client) => void;
  initialData?: Client | null;
}

const GSTClientFormModal: React.FC<GSTClientFormModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Client>>({
    legalName: '',
    tradeName: '',
    status: 'Active Filing',
    gstProfile: {
      gstin: '',
      username: '',
      password: '',
      gstStatus: 'Active',
      regDate: '',
      regType: 'Regular',
      filingFreq: 'Monthly',
      constitution: 'Proprietorship',
      stakeholders: [],
      address: '',
      jurisdictionType: 'State',
      sector: '',
      range: '',
    },
    bankDetails: {
      bankName: '',
      accountNo: '',
      ifsc: ''
    },
    remarks: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({
        legalName: '',
        tradeName: '',
        status: 'Active Filing',
        gstProfile: {
          gstin: '',
          username: '',
          password: '',
          gstStatus: 'Active',
          regDate: '',
          regType: 'Regular',
          filingFreq: 'Monthly',
          constitution: 'Proprietorship',
          stakeholders: [],
          address: '',
          jurisdictionType: 'State',
          sector: '',
          range: '',
        },
        bankDetails: { bankName: '', accountNo: '', ifsc: '' }
      });
    }
    setError(null);
  }, [initialData, isOpen]);

  useEffect(() => {
    const gstin = formData.gstProfile?.gstin || '';
    if (gstin.length >= 12) {
      const pan = gstin.substring(2, 12);
      if (formData.gstProfile?.constitution === 'Proprietorship') {
        const stakeholders = [{
          id: 'proprietor_1',
          name: formData.legalName || '',
          pan: pan,
          mobile: formData.mobile || ''
        }];
        setFormData(prev => ({
          ...prev,
          gstProfile: { ...prev.gstProfile!, stakeholders }
        }));
      }
    }
  }, [formData.gstProfile?.gstin, formData.gstProfile?.constitution, formData.legalName, formData.mobile]);

  const handleGstChange = (field: keyof GSTProfile, value: any) => {
    setFormData(prev => {
      const updatedProfile = { ...prev.gstProfile!, [field]: value };
      if (field === 'regType' && value === 'Composition') {
        updatedProfile.filingFreq = 'Quarterly';
      }
      return { ...prev, gstProfile: updatedProfile };
    });
  };

  const addStakeholder = () => {
    handleGstChange('stakeholders', [
      ...(formData.gstProfile?.stakeholders || []),
      { id: Date.now().toString(), name: '', mobile: '', pan: '' }
    ]);
  };

  const removeStakeholder = (id: string) => {
    handleGstChange('stakeholders', (formData.gstProfile?.stakeholders || []).filter(s => s.id !== id));
  };

  const updateStakeholder = (id: string, field: keyof Stakeholder, value: string) => {
    handleGstChange('stakeholders', (formData.gstProfile?.stakeholders || []).map(s => 
      s.id === id ? { ...s, [field]: value } : s
    ));
  };

  const copyAndOpen = (text: string, url: string) => {
    navigator.clipboard.writeText(text);
    window.open(url, '_blank');
  };

  const validateGstin = (gst: string) => {
    const regex = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;
    return regex.test(gst);
  };

  const handleSave = async () => {
    try {
      if (!formData.gstProfile?.gstin || !validateGstin(formData.gstProfile.gstin)) {
        throw new Error("Invalid GSTIN Format");
      }
      if (!formData.legalName) throw new Error("Legal Name is required");

      const saved = await mockBackend.saveClient(formData);
      onSave(saved);
      onClose();
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      handleGstChange('certificateUrl', file.name);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-4 overflow-hidden">
      <div className="w-full max-w-4xl bg-white rounded-[2rem] shadow-2xl flex flex-col max-h-[95vh] overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="px-8 py-5 border-b border-slate-100 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white shadow-lg">
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            </div>
            <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase">GST Registration Vault</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
            <svg className="h-6 w-6 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        {error && (
          <div className="mx-8 mt-4 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600 font-bold text-sm">
            {error}
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-8 space-y-8 no-scrollbar">

          {/* Identity Section */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Client Status</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none focus:ring-2 focus:ring-indigo-600/20"
                value={formData.status} onChange={e => setFormData({...formData, status: e.target.value as ClientStatus})}>
                <option value="Active Filing">Active Filing</option>
                <option value="Case-by-Case">Case-by-Case</option>
                <option value="Inactive (Temporary)">Inactive (Temporary)</option>
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Mobile Number</label>
              <input type="tel" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.mobile} onChange={e => setFormData({...formData, mobile: e.target.value})} placeholder="Primary contact" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Legal Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold uppercase"
                value={formData.legalName} onChange={e => setFormData({...formData, legalName: e.target.value})} placeholder="AS PER PAN" />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Trade Name</label>
              <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.tradeName} onChange={e => setFormData({...formData, tradeName: e.target.value})} placeholder="Business Name" />
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* GST Details */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="md:col-span-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GSTIN</label>
              <div className="flex gap-2">
                <input className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3 font-black uppercase tracking-widest text-lg"
                  value={formData.gstProfile?.gstin} onChange={e => handleGstChange('gstin', e.target.value.toUpperCase())} placeholder="27XXXXX0000X1Z5" />
                <button onClick={() => copyAndOpen(formData.gstProfile?.gstin || '', 'https://services.gst.gov.in/services/searchtp')}
                  className="px-4 bg-indigo-50 text-indigo-600 rounded-xl border border-indigo-100 hover:bg-indigo-600 hover:text-white transition-all">
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </button>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Portal ID</label>
              <div className="flex gap-2">
                <input className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.username} onChange={e => handleGstChange('username', e.target.value)} />
                <button onClick={() => copyAndOpen(formData.gstProfile?.username || '', 'https://services.gst.gov.in/services/login')}
                  className="px-4 bg-slate-900 text-white rounded-xl hover:bg-indigo-600 transition-all font-black text-[10px] uppercase">Login</button>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Password</label>
              <div className="relative">
                <input type={showPassword ? "text" : "password"} className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.password} onChange={e => handleGstChange('password', e.target.value)} />
                <button onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3 text-slate-400">
                  {showPassword ? <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg> : <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7S1.732 16.057.458 12z" /></svg>}
                </button>
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Jurisdiction Section */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Jurisdiction Type</label>
              <div className="flex gap-4">
                {['State', 'Center'].map(type => (
                  <button key={type} onClick={() => handleGstChange('jurisdictionType', type as JurisdictionType)}
                    className={`flex-1 py-3 rounded-xl border font-black uppercase tracking-widest text-[10px] transition-all ${formData.gstProfile?.jurisdictionType === type ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-slate-50 border-slate-200 text-slate-400 hover:text-slate-600'}`}>
                    {type}
                  </button>
                ))}
              </div>
            </div>
            {formData.gstProfile?.jurisdictionType === 'State' ? (
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Sector</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.sector} onChange={e => handleGstChange('sector', e.target.value)} placeholder="e.g. Sector 10" />
              </div>
            ) : (
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Range</label>
                <input className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                  value={formData.gstProfile?.range} onChange={e => handleGstChange('range', e.target.value)} placeholder="e.g. Range II" />
              </div>
            )}
          </div>

          <hr className="border-slate-100" />

          {/* Status, Type, Frequency */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GSTIN Status</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.gstProfile?.gstStatus} onChange={e => handleGstChange('gstStatus', e.target.value as GstStatus)}>
                <option value="Active">Active</option>
                <option value="Suspended">Suspended</option>
                <option value="Cancelled">Cancelled</option>
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Reg. Date</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold"
                value={formData.gstProfile?.regDate} onChange={e => handleGstChange('regDate', e.target.value)} />
            </div>
            {formData.gstProfile?.gstStatus === 'Cancelled' && (
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Cancel Date</label>
                <input type="date" className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold text-red-600"
                  value={formData.gstProfile?.cancelDate} onChange={e => handleGstChange('cancelDate', e.target.value)} />
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Reg. Type</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.gstProfile?.regType} onChange={e => handleGstChange('regType', e.target.value as GstRegType)}>
                <option value="Regular">Regular</option>
                <option value="Composition">Composition</option>
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Filing Freq</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none disabled:opacity-50"
                disabled={formData.gstProfile?.regType === 'Composition'}
                value={formData.gstProfile?.filingFreq} onChange={e => handleGstChange('filingFreq', e.target.value as GstFilingFreq)}>
                <option value="Monthly">Monthly</option>
                <option value="Quarterly">Quarterly</option>
              </select>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Constitution & Stakeholders */}
          <div className="space-y-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Constitution</label>
              <select className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold outline-none"
                value={formData.gstProfile?.constitution} onChange={e => handleGstChange('constitution', e.target.value as ConstitutionType)}>
                <option value="Proprietorship">Proprietorship</option>
                <option value="Partnership">Partnership</option>
                <option value="HUF">HUF</option>
                <option value="Company">Company</option>
                <option value="Trust">Trust</option>
              </select>
            </div>

            <div className="bg-slate-50 rounded-2xl p-6 border border-slate-100 space-y-4">
              <div className="flex items-center justify-between">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500">Personnel Details</h4>
                {formData.gstProfile?.constitution !== 'Proprietorship' && (
                  <button onClick={addStakeholder} className="text-[9px] font-black uppercase bg-indigo-600 text-white px-3 py-1.5 rounded-lg shadow-sm">+ Add Personnel</button>
                )}
              </div>

              <div className="space-y-4">
                {(formData.gstProfile?.stakeholders || []).map((s) => (
                  <div key={s.id} className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end bg-white p-4 rounded-xl shadow-sm border border-slate-100 animate-in slide-in-from-left-2">
                    <div className="md:col-span-1">
                      <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">Name</label>
                      <input className="w-full border-slate-200 rounded-lg p-2 text-sm font-bold disabled:bg-slate-50 uppercase"
                        disabled={formData.gstProfile?.constitution === 'Proprietorship'}
                        value={s.name} onChange={e => updateStakeholder(s.id, 'name', e.target.value)} />
                    </div>
                    <div>
                      <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">PAN</label>
                      <input className="w-full border-slate-200 rounded-lg p-2 text-sm font-bold disabled:bg-slate-50 uppercase"
                        disabled={formData.gstProfile?.constitution === 'Proprietorship'}
                        value={s.pan} onChange={e => updateStakeholder(s.id, 'pan', e.target.value.toUpperCase())} />
                    </div>
                    <div>
                      <label className="text-[9px] font-black uppercase text-slate-400 mb-1 block">Mobile</label>
                      <input className="w-full border-slate-200 rounded-lg p-2 text-sm font-bold"
                        value={s.mobile} onChange={e => updateStakeholder(s.id, 'mobile', e.target.value)} />
                    </div>
                    {formData.gstProfile?.constitution !== 'Proprietorship' && (
                      <button onClick={() => removeStakeholder(s.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg">
                         <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <hr className="border-slate-100" />

          {/* Certificate & Misc */}
          <div className="space-y-6">
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">GST Certificate (PDF)</label>
              <div className="flex items-center gap-3 bg-slate-50 border border-slate-200 rounded-xl p-3 group hover:border-indigo-300 transition-colors cursor-pointer"
                   onClick={() => fileInputRef.current?.click()}>
                 <div className="h-10 w-10 rounded-lg bg-white border border-slate-200 flex items-center justify-center text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-sm">
                    <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                 </div>
                 <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileUpload} />
                 <span className="text-xs font-bold text-slate-500">{formData.gstProfile?.certificateUrl || 'Click to select PDF document'}</span>
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Address</label>
              <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold h-24"
                value={formData.gstProfile?.address} onChange={e => handleGstChange('address', e.target.value)} />
            </div>
            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1.5 block">Remarks</label>
              <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold h-24"
                value={formData.remarks} onChange={e => setFormData({...formData, remarks: e.target.value})} />
            </div>
          </div>
        </div>

        <div className="p-8 border-t border-slate-100 flex gap-4 bg-slate-50/50">
          <button onClick={onClose} className="flex-1 py-4 rounded-xl text-slate-500 font-black uppercase text-[10px] border border-slate-200">Discard</button>
          <button onClick={handleSave} className="flex-[2] bg-indigo-600 text-white font-black uppercase text-[10px] py-4 rounded-xl shadow-xl hover:bg-slate-900 transition-all">
            {initialData ? 'Update Entity' : 'Save New GST Client'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default GSTClientFormModal;

import React, { useState, useEffect, useMemo } from 'react';
import { Client, JurisdictionType } from '../../types';
import { mockBackend } from '../../services/mockBackend';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import ITClientFormModal from '../Clientform/ITClientFormModal';
import Loader from '../../components/Loader';

interface MasterPortfolioProps {
  filter?: 'gst' | 'it';
  externalSearch?: string;
  hideInternalSearch?: boolean;
  jurisdictionFilter?: JurisdictionType | 'All';
}

const MasterPortfolio: React.FC<MasterPortfolioProps> = ({ 
  filter, 
  externalSearch = '', 
  hideInternalSearch = false,
  jurisdictionFilter = 'All'
}) => {
  const [clients, setClients] = useState<Client[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [isGstModalOpen, setIsGstModalOpen] = useState(false);
  const [isItModalOpen, setIsItModalOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);

  const fetchClients = async () => {
    setIsLoading(true);
    try {
      const data = await mockBackend.getClients();
      setClients(data || []);
    } catch (error) {
      console.error("Failed to fetch clients", error);
      setClients([]);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const filteredClients = useMemo(() => {
    let list = Array.isArray(clients) ? clients : [];

    if (filter === 'gst') {
      list = list.filter(c => !!c.gstProfile);
      if (jurisdictionFilter !== 'All') {
        list = list.filter(c => c.gstProfile?.jurisdictionType === jurisdictionFilter);
      }
    } else if (filter === 'it') {
      list = list.filter(c => !!c.itProfile);
    }

    const s = (externalSearch || search || '').toLowerCase();
    return list.filter(c => 
      (c.legalName || '').toLowerCase().includes(s) || 
      (c.tradeName || '').toLowerCase().includes(s) || 
      (c.gstProfile?.gstin && c.gstProfile.gstin.toLowerCase().includes(s)) || 
      (c.mobile || '').includes(s)
    );
  }, [clients, search, externalSearch, filter, jurisdictionFilter]);

  const handleEdit = (client: Client) => {
    setSelectedClient(client);
    if (client.gstProfile) {
      setIsGstModalOpen(true);
    } else {
      setIsItModalOpen(true);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this client record?')) {
      await mockBackend.deleteClient(id);
      fetchClients();
    }
  };

  if (isLoading) return <Loader />;

  return (
    <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-500">
      {!hideInternalSearch && !externalSearch && (
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-4 shrink-0">
          <div className="relative flex-1 max-w-xl group">
            <input 
              type="text" 
              placeholder="Search legal name or identifier..."
              className="w-full bg-white border border-slate-200 rounded-2xl py-4 pl-12 pr-6 font-bold text-slate-900 shadow-sm focus:ring-4 focus:ring-indigo-50 transition-all outline-none"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
            <svg className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>
      )}

      <div className="flex-1 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="overflow-auto no-scrollbar flex-1">
          <table className="w-full text-left border-collapse min-w-[900px]">
            <thead className="sticky top-0 z-20">
              <tr className="bg-slate-50 border-b border-slate-100">
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Legal Entity</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Identifier (GSTIN)</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50">Jurisdiction</th>
                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 bg-slate-50 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredClients.length === 0 ? (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-400 font-bold uppercase tracking-widest text-xs">No records found</td>
                </tr>
              ) : (
                filteredClients.map((client) => (
                  <tr key={client.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-6">
                      <p className="text-base font-black text-slate-900 leading-tight">{client.legalName}</p>
                      <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-tight">{client.tradeName || 'No Trade Name'}</p>
                    </td>
                    <td className="px-8 py-6">
                      {client.gstProfile && (
                        <div className="flex items-center gap-2">
                           <div className="h-5 w-5 rounded-md bg-blue-50 flex items-center justify-center text-blue-600 font-black text-[10px]">G</div>
                           <span className="text-[11px] font-bold text-slate-600 font-mono uppercase tracking-widest">{client.gstProfile.gstin}</span>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex flex-col">
                        <span className="px-2 py-0.5 rounded bg-slate-100 text-[9px] font-black text-slate-500 uppercase tracking-widest w-fit mb-1">
                          {client.gstProfile?.jurisdictionType || 'N/A'}
                        </span>
                        <span className="text-[10px] font-bold text-slate-400 uppercase">
                          {client.gstProfile?.jurisdictionType === 'State' ? client.gstProfile.sector : client.gstProfile?.range}
                        </span>
                      </div>
                    </td>
                    <td className="px-8 py-6 text-right">
                      <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleEdit(client)} className="h-9 w-9 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200 shadow-sm flex items-center justify-center">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                        </button>
                        <button onClick={() => handleDelete(client.id)} className="h-9 w-9 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-red-600 hover:border-red-200 shadow-sm flex items-center justify-center">
                          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <GSTClientFormModal isOpen={isGstModalOpen} onClose={() => setIsGstModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />
      <ITClientFormModal isOpen={isItModalOpen} onClose={() => setIsItModalOpen(false)} onSave={() => fetchClients()} initialData={selectedClient} />
    </div>
  );
};

export default MasterPortfolio;

import React, { useState, useEffect, useMemo } from 'react';
import MasterPortfolio from './MasterPortfolio';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, JurisdictionType } from '../../types';

const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [jurisdictionFilter, setJurisdictionFilter] = useState<JurisdictionType | 'All'>('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const load = async () => {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    };
    load();
  }, [refreshTrigger]);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  const handleExportCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Status", "Jurisdiction", "Sector/Range"];
    const rows = clients.map(c => [
      c.legalName,
      c.tradeName,
      c.mobile,
      c.gstProfile?.gstin,
      c.status,
      c.gstProfile?.jurisdictionType,
      c.gstProfile?.jurisdictionType === 'State' ? c.gstProfile.sector : c.gstProfile?.range
    ]);
    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_clients.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleImportTemplateCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Status", "Jurisdiction", "Sector/Range"];
    const csvContent = [headers].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_template.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      let successCount = 0;
      for (const row of rows) {
        const cols = row.split(',');
        if (cols.length < 4) continue;
        const gstin = cols[3]?.trim();
        if (!gstin) continue;
        try {
          await mockBackend.saveClient({
            legalName: cols[0]?.trim(),
            tradeName: cols[1]?.trim(),
            mobile: cols[2]?.trim(),
            status: 'Active Filing',
            gstProfile: {
              gstin,
              username: '',
              password: '',
              gstStatus: 'Active',
              regDate: new Date().toISOString().split('T')[0],
              regType: 'Regular',
              filingFreq: 'Monthly',
              constitution: 'Proprietorship',
              stakeholders: [],
              jurisdictionType: (cols[5]?.trim() as any) || 'State',
              sector: cols[6]?.trim() || '',
            }
          });
          successCount++;
        } catch (err) {}
      }
      alert(`Import complete: ${successCount} entries added.`);
      setRefreshTrigger(p => p + 1);
      setShowDataOptions(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="flex flex-col h-full space-y-4 pb-4 overflow-hidden">
      {/* Consolidated Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-4 bg-white p-3 rounded-[1.5rem] border border-slate-200 shadow-sm shrink-0">

        {/* Status Indicators (Compact) */}
        <div className="flex items-center gap-4 px-2 border-r border-slate-100 hidden xl:flex">
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-slate-400 uppercase leading-none mb-1">Total</span>
            <span className="text-lg font-black text-slate-900 leading-none">{stats.total}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-green-500 uppercase leading-none mb-1">Active</span>
            <span className="text-lg font-black text-green-600 leading-none">{stats.active}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-amber-500 uppercase leading-none mb-1">Case</span>
            <span className="text-lg font-black text-amber-600 leading-none">{stats.caseStudy}</span>
          </div>
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-red-400 uppercase leading-none mb-1">Inact</span>
            <span className="text-lg font-black text-red-500 leading-none">{stats.inactive}</span>
          </div>
        </div>

        {/* Unified Search */}
        <div className="relative flex-1 group min-w-[200px] w-full lg:w-auto">
          <input type="text" placeholder="Search entity..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-3 pl-10 pr-4 font-bold text-sm text-slate-900 focus:ring-2 focus:ring-indigo-600/10 transition-all outline-none" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {/* Jurisdiction Filter */}
        <select value={jurisdictionFilter} onChange={e => setJurisdictionFilter(e.target.value as any)}
          className="bg-slate-50 border-none rounded-xl px-4 py-3 text-xs font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-40">
          <option value="All">All Jurisdiction</option>
          <option value="State">State Only</option>
          <option value="Center">Center Only</option>
        </select>

        {/* Combined Data Icon (Import/Export) */}
        <div className="relative shrink-0">
          <button onClick={() => setShowDataOptions(!showDataOptions)} className="h-11 w-11 flex items-center justify-center bg-slate-100 rounded-xl text-slate-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
             <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7v10c0 2 1 3 3 3h10c2 0 3-1 3-3V7c0-2-1-3-3-3H7C5 4 4 5 4 7zm4 4h8m-8 4h5" /></svg>
          </button>
          {showDataOptions && (
            <div className="absolute right-0 mt-2 w-52 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden animate-in zoom-in-95">
              <button onClick={handleImportTemplateCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl">CSV Template</button>
              <label className="w-full block px-4 py-3 text-[10px] font-black uppercase tracking-widest text-indigo-600 hover:bg-slate-50 rounded-xl cursor-pointer">
                Upload CSV <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              </label>
              <button onClick={handleExportCSV} className="w-full text-left px-4 py-3 text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-xl border-t border-slate-50 mt-1">Export Data</button>
            </div>
          )}
        </div>

        {/* Add Client Button */}
        <button onClick={() => setIsModalOpen(true)} className="bg-indigo-600 text-white font-black uppercase tracking-tight px-5 h-11 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2 shrink-0 text-lg whitespace-nowrap">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add Client
        </button>
      </div>

      <div className="flex-1 min-h-0 bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <MasterPortfolio key={refreshTrigger} filter="gst" externalSearch={search} hideInternalSearch={true} jurisdictionFilter={jurisdictionFilter} />
      </div>

      <GSTClientFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={() => setRefreshTrigger(p => p + 1)} />
    </div>
  );
};

export default GSTPortfolio;

