import React, { useState, useEffect, useMemo } from 'react';
import MasterPortfolio from './MasterPortfolio';
import GSTClientFormModal from '../Clientform/GSTClientFormModal';
import { mockBackend } from '../../services/mockBackend';
import { Client, JurisdictionType } from '../../types';

const GSTPortfolio: React.FC = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  const [search, setSearch] = useState('');
  const [jurisdictionFilter, setJurisdictionFilter] = useState<JurisdictionType | 'All'>('All');
  const [subFilter, setSubFilter] = useState('All');
  const [showDataOptions, setShowDataOptions] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);

  useEffect(() => {
    const load = async () => {
      const data = await mockBackend.getClients();
      setClients(data.filter(c => !!c.gstProfile));
    };
    load();
  }, [refreshTrigger]);

  const stats = useMemo(() => {
    const total = clients.length;
    const active = clients.filter(c => c.status === 'Active Filing').length;
    const caseStudy = clients.filter(c => c.status === 'Case-by-Case').length;
    const inactive = clients.filter(c => c.status.startsWith('Inactive')).length;
    return { total, active, caseStudy, inactive };
  }, [clients]);

  // Extract unique Sectors or Ranges for the sub-dropdown based on selected jurisdiction
  const subOptions = useMemo(() => {
    if (jurisdictionFilter === 'All') return [];
    const set = new Set<string>();
    clients.forEach(c => {
      if (c.gstProfile?.jurisdictionType === jurisdictionFilter) {
        const val = jurisdictionFilter === 'State' ? c.gstProfile.sector : c.gstProfile.range;
        if (val) set.add(val);
      }
    });
    return Array.from(set).sort();
  }, [clients, jurisdictionFilter]);

  // Reset sub-filter whenever main jurisdiction filter changes
  useEffect(() => {
    setSubFilter('All');
  }, [jurisdictionFilter]);

  const handleExportCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Status", "Jurisdiction", "Sector/Range"];
    const rows = clients.map(c => [
      c.legalName,
      c.tradeName,
      c.mobile,
      c.gstProfile?.gstin,
      c.status,
      c.gstProfile?.jurisdictionType,
      c.gstProfile?.jurisdictionType === 'State' ? c.gstProfile.sector : c.gstProfile?.range
    ]);
    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_clients_export.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleImportTemplateCSV = () => {
    const headers = ["Legal Name", "Trade Name", "Mobile", "GSTIN", "Status", "Jurisdiction", "Sector/Range"];
    const csvContent = [headers].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "gst_template.csv");
    link.click();
    setShowDataOptions(false);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').slice(1);
      let successCount = 0;
      for (const row of rows) {
        const cols = row.split(',');
        if (cols.length < 4) continue;
        const gstin = cols[3]?.trim();
        if (!gstin) continue;
        try {
          await mockBackend.saveClient({
            legalName: cols[0]?.trim(),
            tradeName: cols[1]?.trim(),
            mobile: cols[2]?.trim(),
            status: 'Active Filing',
            gstProfile: {
              gstin,
              username: '',
              password: '',
              gstStatus: 'Active',
              regDate: new Date().toISOString().split('T')[0],
              regType: 'Regular',
              filingFreq: 'Monthly',
              constitution: 'Proprietorship',
              stakeholders: [],
              jurisdictionType: (cols[5]?.trim() as any) || 'State',
              sector: cols[6]?.trim() || '',
            }
          });
          successCount++;
        } catch (err) {}
      }
      alert(`Import complete: ${successCount} added.`);
      setRefreshTrigger(p => p + 1);
      setShowDataOptions(false);
    };
    reader.readAsText(file);
  };

  return (
    <div className="flex flex-col h-full space-y-3 -mt-3"> {/* -mt-3 to decrease space between header and first line */}
      {/* Consolidated Toolbar */}
      <div className="flex flex-col lg:flex-row items-center gap-3 bg-white p-2.5 rounded-[1.25rem] border border-slate-200 shadow-sm shrink-0">

        {/* Status Indicators */}
        <div className="flex items-center gap-3 px-2 border-r border-slate-100 hidden xl:flex shrink-0">
          <div className="flex flex-col items-center px-1">
            <span className="text-[8px] font-black text-slate-400 uppercase leading-none mb-1">Total</span>
            <span className="text-base font-black text-slate-900 leading-none">{stats.total}</span>
          </div>
          <div className="flex flex-col items-center px-1">
            <span className="text-[8px] font-black text-green-500 uppercase leading-none mb-1">Active</span>
            <span className="text-base font-black text-green-600 leading-none">{stats.active}</span>
          </div>
          <div className="flex flex-col items-center px-1">
            <span className="text-[8px] font-black text-amber-500 uppercase leading-none mb-1">Case</span>
            <span className="text-base font-black text-amber-600 leading-none">{stats.caseStudy}</span>
          </div>
          <div className="flex flex-col items-center px-1">
            <span className="text-[8px] font-black text-red-400 uppercase leading-none mb-1">Inact</span>
            <span className="text-base font-black text-red-500 leading-none">{stats.inactive}</span>
          </div>
        </div>

        {/* Unified Search */}
        <div className="relative flex-1 group min-w-[150px] w-full lg:w-auto">
          <input type="text" placeholder="Search entity..." value={search} onChange={e => setSearch(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-xl py-2 pl-9 pr-4 font-bold text-xs text-slate-900 focus:ring-2 focus:ring-indigo-600/10 outline-none" />
          <svg className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        {/* Jurisdiction Primary Filter */}
        <select value={jurisdictionFilter} onChange={e => setJurisdictionFilter(e.target.value as any)}
          className="bg-slate-50 border-none rounded-xl px-3 py-2 text-[10px] font-black uppercase tracking-widest text-slate-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-36 shrink-0">
          <option value="All">All Jurisdiction</option>
          <option value="State">State</option>
          <option value="Center">Center</option>
        </select>

        {/* Sub-Filter (Sector/Range) - Only shows if a jurisdiction is selected */}
        {jurisdictionFilter !== 'All' && (
          <select value={subFilter} onChange={e => setSubFilter(e.target.value)}
            className="bg-slate-50 border-none rounded-xl px-3 py-2 text-[10px] font-black uppercase tracking-widest text-indigo-600 focus:ring-2 focus:ring-indigo-600/10 outline-none w-full lg:w-40 shrink-0 animate-in slide-in-from-right-2">
            <option value="All">All {jurisdictionFilter === 'State' ? 'Sectors' : 'Ranges'}</option>
            {subOptions.map(opt => (
              <option key={opt} value={opt}>{opt}</option>
            ))}
          </select>
        )}

        {/* Data Tools */}
        <div className="relative shrink-0">
          <button onClick={() => setShowDataOptions(!showDataOptions)} className="h-9 w-9 flex items-center justify-center bg-slate-100 rounded-xl text-slate-600 hover:bg-indigo-600 hover:text-white transition-all shadow-sm">
             <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7v10c0 2 1 3 3 3h10c2 0 3-1 3-3V7c0-2-1-3-3-3H7C5 4 4 5 4 7zm4 4h8m-8 4h5" /></svg>
          </button>
          {showDataOptions && (
            <div className="absolute right-0 mt-2 w-44 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 overflow-hidden animate-in zoom-in-95">
              <button onClick={handleImportTemplateCSV} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-lg">CSV Template</button>
              <label className="w-full block px-3 py-2 text-[9px] font-black uppercase tracking-widest text-indigo-600 hover:bg-slate-50 rounded-lg cursor-pointer">
                Upload CSV <input type="file" accept=".csv" className="hidden" onChange={handleFileUpload} />
              </label>
              <button onClick={handleExportCSV} className="w-full text-left px-3 py-2 text-[9px] font-black uppercase tracking-widest text-slate-600 hover:bg-slate-50 rounded-lg border-t border-slate-50 mt-1 pt-2">Export CSV</button>
            </div>
          )}
        </div>

        {/* Add Client Button */}
        <button onClick={() => setIsModalOpen(true)} className="bg-indigo-600 text-white font-black uppercase tracking-tight px-4 h-9 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center gap-2 shrink-0 text-sm whitespace-nowrap">
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Add Client
        </button>
      </div>

      <div className="flex-1 min-h-0 bg-white rounded-[1.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <MasterPortfolio 
          key={refreshTrigger} 
          filter="gst" 
          externalSearch={search} 
          hideInternalSearch={true} 
          jurisdictionFilter={jurisdictionFilter}
          subFilter={subFilter} 
        />
      </div>

      <GSTClientFormModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={() => setRefreshTrigger(p => p + 1)} />
    </div>
  );
};

